  var branchFallback = buildBranchLookupMap(BRANCH_FALLBACK_DEFAULT);
  var branchMaster = new Map();
  var branchMasterMeta = { source: 'built-in', label: '' };
  var lastRawSheet = null; // { headerRow, dataRows } of the last raw file loaded, for re-processing after a master update

  function buildBranchMasterMap(rows){
    var m = new Map();
    rows.forEach(function(r){
      m.set(r[0], { branch: r[1], region: r[2], controllingBranch: r[3] });
    });
    return m;
  }

  function buildBranchLookupMap(rows){
    var m = new Map();
    rows.forEach(function(r){
      m.set(r[0], { branch: r[1], controllingBranch: r[2] });
    });
    return m;
  }

  function loadBranchMaster(){
    var custom = null;
    try{
      var raw = localStorage.getItem('topayBranchMasterOverride');
      if (raw) custom = JSON.parse(raw);
    }catch(e){ custom = null; }
    if (custom && custom.rows && custom.rows.length){
      branchMaster = buildBranchMasterMap(custom.rows);
      branchMasterMeta = { source: 'custom', label: custom.label || 'custom upload' };
    } else {
      branchMaster = buildBranchMasterMap(BRANCH_MASTER_DEFAULT);
      branchMasterMeta = { source: 'built-in', label: '' };
    }
    updateMasterStatusText();
  }

  function updateMasterStatusText(){
    var count = branchMaster.size;
    var fbNote = ' + ' + branchFallback.size.toLocaleString() + ' in the secondary branch-details lookup (used when a code isn\'t in the main list)';
    var text;
    if (branchMasterMeta.source === 'custom'){
      text = count.toLocaleString() + ' branches loaded (from your upload: ' + branchMasterMeta.label + ')' + fbNote;
    } else {
      text = count.toLocaleString() + ' branches loaded (built-in master — use "Update branch/region master" below if your branch list has changed)' + fbNote;
    }
    // ToPay and Paid generators share the same branch master, so both status
    // lines (if present on the page) get the same text.
    ['masterStatus', 'paidMasterStatus', 'combinedMasterStatus'].forEach(function(id){
      var el = document.getElementById(id);
      if (el) el.textContent = text;
    });
  }


  var downloadsPromise = (function(){
    try{
      if (typeof window.claude !== 'undefined' && typeof window.claude.use === 'function'){
        return window.claude.use('downloads').catch(function(){ return null; });
      }
    }catch(e){}
    return Promise.resolve(null);
  })();

  /* ---------- Date parsing ---------- */
  function excelSerialToDate(serial){
    var utcDays = Math.floor(serial - 25569);
    var utcValue = utcDays * 86400;
    return new Date(utcValue * 1000);
  }

  function parseDateValue(v){
    if (v === null || v === undefined || v === '') return null;
    if (v instanceof Date){
      if (isNaN(v.getTime())) return null;
      return { y: v.getFullYear(), m: v.getMonth() + 1 };
    }
    if (typeof v === 'number'){
      if (!isFinite(v) || v <= 0) return null;
      var d = excelSerialToDate(v);
      if (isNaN(d.getTime())) return null;
      return { y: d.getUTCFullYear(), m: d.getUTCMonth() + 1 };
    }
    if (typeof v === 'string'){
      var s = v.trim();
      if (!s) return null;
      var m1 = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ]\d{1,2}:\d{2}(:\d{2})?)?$/);
      if (m1) return { y: +m1[1], m: +m1[2] };
      var m2 = s.match(/^(\d{1,2})[.\-\/](\d{1,2})[.\-\/](\d{4})/);
      if (m2) return { y: +m2[3], m: +m2[2] };
      var m3 = s.match(/^(\d{4})[\/](\d{1,2})[\/](\d{1,2})/);
      if (m3) return { y: +m3[1], m: +m3[2] };
      var d2 = new Date(s);
      if (!isNaN(d2.getTime())) return { y: d2.getFullYear(), m: d2.getMonth() + 1 };
      return null;
    }
    return null;
  }

  var MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  function monthLabel(y, m){ return MONTH_NAMES[m-1] + '-' + String(y).slice(-2); }

  /* ---------- Header matching ---------- */
  function normalizeHeader(h){
    return String(h == null ? '' : h).trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
  }
  function findColIndex(headerRow, target){
    for (var i = 0; i < headerRow.length; i++){
      if (normalizeHeader(headerRow[i]) === target) return i;
    }
    return -1;
  }
  function headerHasAny(headerRow, targets){
    for (var i = 0; i < headerRow.length; i++){
      var n = normalizeHeader(headerRow[i]);
      if (targets.indexOf(n) !== -1) return true;
    }
    return false;
  }

  function detectType(sheetName, headerRow){
    var n = normalizeHeader(sheetName);
    if (n === 'PAID') return 'paid';
    if (n === 'TOPAY' || n === 'TOPAID') return 'topay';
    if (headerHasAny(headerRow, ['CNBLLINGPARTYCODE','BLLINGPARTYDETAILS','CNBILLINGPARTYCODE','BILLINGPARTYDETAILS'])) return 'paid';
    if (headerHasAny(headerRow, ['CHLNCHLNNO','CHLNLORRYNO'])) return 'topay';
    return 'unknown';
  }

  /* ---------- Pivot builder ---------- */
  function buildPivot(dataRows, bcodeIdx, branchIdx, dateIdx, noDateLabel){
    var monthsMap = {};      // "y-m" -> {y,m}
    var bcodeMap = {};       // bcode -> {branch, counts:{}, noDate:0, order}
    var order = [];
    var totalRows = 0, noDateTotal = 0;

    for (var r = 0; r < dataRows.length; r++){
      var row = dataRows[r];
      var bcodeRaw = row[bcodeIdx];
      if (bcodeRaw === null || bcodeRaw === undefined || bcodeRaw === '') continue;
      var bcode = String(bcodeRaw).trim();
      var branch = branchIdx >= 0 && row[branchIdx] != null ? String(row[branchIdx]).trim() : '';
      var dateVal = dateIdx >= 0 ? row[dateIdx] : null;
      var parsed = parseDateValue(dateVal);

      totalRows++;
      if (!bcodeMap[bcode]){
        bcodeMap[bcode] = { branch: branch, counts: {}, noDate: 0 };
        order.push(bcode);
      }
      if (branch && !bcodeMap[bcode].branch) bcodeMap[bcode].branch = branch;

      if (parsed){
        var key = parsed.y + '-' + parsed.m;
        monthsMap[key] = parsed;
        bcodeMap[bcode].counts[key] = (bcodeMap[bcode].counts[key] || 0) + 1;
      } else {
        bcodeMap[bcode].noDate++;
        noDateTotal++;
      }
    }

    var months = Object.keys(monthsMap).map(function(k){ return monthsMap[k]; });
    months.sort(function(a,b){ return a.y - b.y || a.m - b.m; });

    order.sort(function(a,b){
      var na = Number(a), nb = Number(b);
      if (!isNaN(na) && !isNaN(nb)) return na - nb;
      return a.localeCompare(b);
    });

    var showNoDate = noDateTotal > 0;
    var headers = ['B.CODE','BRANCH'];
    months.forEach(function(mo){ headers.push(monthLabel(mo.y, mo.m)); });
    if (showNoDate) headers.push(noDateLabel);
    headers.push('Total Result');

    var rows = order.map(function(bcode){
      var entry = bcodeMap[bcode];
      var line = [bcode, entry.branch];
      var rowTotal = 0;
      months.forEach(function(mo){
        var key = mo.y + '-' + mo.m;
        var c = entry.counts[key] || 0;
        line.push(c);
        rowTotal += c;
      });
      if (showNoDate){ line.push(entry.noDate); rowTotal += entry.noDate; }
      line.push(rowTotal);
      return line;
    });

    var totalRow = ['Total Result', ''];
    var grand = 0;
    var numCols = months.length + (showNoDate ? 1 : 0);
    for (var c2 = 0; c2 < numCols; c2++){
      var colSum = 0;
      for (var ri = 0; ri < rows.length; ri++){ colSum += rows[ri][2 + c2]; }
      totalRow.push(colSum);
      grand += colSum;
    }
    totalRow.push(grand);

    return {
      headers: headers, rows: rows, totalRow: totalRow,
      totalRecords: totalRows, noDateTotal: noDateTotal, showNoDate: showNoDate,
      bcodeCount: order.length, monthCount: months.length
    };
  }

  /* ---------- Ask: month/year + full-datetime parsing ---------- */
  var MONTH_ABBR = {jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12};
  var MONTH_RE = /\b(january|jan|february|feb|march|mar|april|apr|may|june|jun|july|jul|august|aug|september|sept|sep|october|oct|november|nov|december|dec)\b[\s,\-]*'?(\d{2,4})?/;

  function extractMonthYear(lower){
    var m = lower.match(MONTH_RE);
    if (!m) return null;
    var month = MONTH_ABBR[m[1].slice(0,3)];
    var year = null;
    if (m[2]){
      year = m[2].length <= 2 ? 2000 + parseInt(m[2],10) : parseInt(m[2],10);
    }
    return { month: month, year: year, matchedText: m[0] };
  }

  function parseFullDateTime(v){
    if (v === null || v === undefined || v === '') return null;
    if (v instanceof Date){ return isNaN(v.getTime()) ? null : v; }
    if (typeof v === 'number'){
      if (!isFinite(v) || v <= 0) return null;
      var d = excelSerialToDate(v);
      return isNaN(d.getTime()) ? null : d;
    }
    if (typeof v === 'string'){
      var s = v.trim();
      if (!s) return null;
      var m1 = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2}))?)?$/);
      if (m1) return new Date(+m1[1], +m1[2]-1, +m1[3], +(m1[4]||0), +(m1[5]||0), +(m1[6]||0));
      var m2 = s.match(/^(\d{1,2})[.\-\/](\d{1,2})[.\-\/](\d{4})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
      if (m2) return new Date(+m2[3], +m2[2]-1, +m2[1], +(m2[4]||0), +(m2[5]||0), +(m2[6]||0));
      var d2 = new Date(s);
      return isNaN(d2.getTime()) ? null : d2;
    }
    return null;
  }

  function formatDateDisplay(d){
    if (!d) return null;
    var MN = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    var s = d.getDate() + ' ' + MN[d.getMonth()] + ' ' + d.getFullYear();
    if (d.getHours() || d.getMinutes()){
      var hh = d.getHours(), mm = d.getMinutes();
      var ampm = hh >= 12 ? 'PM' : 'AM';
      var hh12 = hh % 12; if (hh12 === 0) hh12 = 12;
      s += ', ' + hh12 + ':' + (mm < 10 ? '0' : '') + mm + ' ' + ampm;
    }
    return s;
  }

  function filterCount(dataRows, idx, opts){
    var count = 0, amountSum = 0, hasAmount = idx.amountIdx >= 0;
    for (var i = 0; i < dataRows.length; i++){
      var row = dataRows[i];
      if (opts.bcode){
        var bc = row[idx.bcodeIdx];
        if (bc == null || String(bc).trim() !== opts.bcode) continue;
      }
      if (opts.month){
        var parsed = idx.dateIdx >= 0 ? parseDateValue(row[idx.dateIdx]) : null;
        if (!parsed || parsed.m !== opts.month) continue;
        if (opts.year && parsed.y !== opts.year) continue;
      }
      count++;
      if (hasAmount){
        var av = row[idx.amountIdx];
        var num = typeof av === 'number' ? av : parseFloat(av);
        if (!isNaN(num)) amountSum += num;
      }
    }
    return { count: count, amountSum: hasAmount ? amountSum : null };
  }

  function formatDocketDetails(tok, block, row){
    var pairs = [];
    block.headerRow.forEach(function(h, i){
      if (!h) return;
      var raw = row[i];
      if (raw === null || raw === undefined || raw === '') return;
      var norm = normalizeHeader(h);
      var display;
      if (norm === 'CNDATE' || norm === 'DELIVERYDATE' || norm === 'MANUALDATE'){
        var dt = parseFullDateTime(raw);
        display = dt ? formatDateDisplay(dt) : String(raw);
      } else if (norm === 'CNAMOUNT'){
        var num = typeof raw === 'number' ? raw : parseFloat(raw);
        display = !isNaN(num) ? ('\u20b9' + num.toLocaleString()) : String(raw);
      } else {
        display = String(raw);
      }
      pairs.push([h, display]);
    });
    return { type: 'docket', heading: block.name + ' \u2014 CN / docket ' + tok, pairs: pairs };
  }

  function answerQuery(rawText){
    var text = String(rawText || '').trim();
    if (!text) return [{ type: 'text', text: 'Type a B.CODE, a month, or a CN / docket number.' }];
    var lower = text.toLowerCase();

    var docketTokens = [];
    (lower.match(/\d{5,}/g) || []).forEach(function(t){ if (docketTokens.indexOf(t) === -1) docketTokens.push(t); });

    if (docketTokens.length){
      var results = [];
      docketTokens.forEach(function(tok){
        var found = false;
        loadedBlocks.filter(function(b){ return b.valid; }).forEach(function(block){
          block.dataRows.forEach(function(row){
            var v1 = block.cnNoIdx >= 0 ? row[block.cnNoIdx] : null;
            var v2 = block.manualCnNoIdx >= 0 ? row[block.manualCnNoIdx] : null;
            if ((v1 != null && String(v1).trim() === tok) || (v2 != null && String(v2).trim() === tok)){
              found = true;
              results.push(formatDocketDetails(tok, block, row));
            }
          });
        });
        if (!found) results.push({ type: 'text', text: 'No record found for CN / docket number ' + tok + ' in the loaded data.' });
      });
      return results;
    }

    var monthInfo = extractMonthYear(lower);
    var withoutMonth = monthInfo ? lower.split(monthInfo.matchedText).join(' ') : lower;
    var bcodeMatch = withoutMonth.match(/\b\d{1,4}\b/);
    var bcode = bcodeMatch ? bcodeMatch[0] : null;

    var wantsTopay = /topay|to\s*-?\s*pay/.test(lower);
    var wantsPaid = /\bpaid\b/.test(lower);

    var targets = loadedBlocks.filter(function(b){ return b.valid; });
    if (wantsTopay && !wantsPaid) targets = targets.filter(function(b){ return detectType(b.name, b.headerRow) === 'topay'; });
    else if (wantsPaid && !wantsTopay) targets = targets.filter(function(b){ return detectType(b.name, b.headerRow) === 'paid'; });

    if (!targets.length){
      return [{ type: 'text', text: 'No matching data is loaded for that yet \u2014 upload the relevant Paid or ToPay export first.' }];
    }

    var lines = [];
    targets.forEach(function(block){
      var blockType = detectType(block.name, block.headerRow);
      var dateIdx, colLabel;
      if (blockType === 'topay' && block.deliveryIdx >= 0){ dateIdx = block.deliveryIdx; colLabel = 'DELIVERY_DATE'; }
      else if (blockType === 'paid' && block.cnIdx >= 0){ dateIdx = block.cnIdx; colLabel = 'CN_DATE'; }
      else if (block.cnIdx >= 0){ dateIdx = block.cnIdx; colLabel = 'CN_DATE'; }
      else { dateIdx = block.deliveryIdx; colLabel = 'DELIVERY_DATE'; }

      var res = filterCount(block.dataRows,
        { bcodeIdx: block.bcodeIdx, dateIdx: dateIdx, amountIdx: block.amountIdx },
        { bcode: bcode, month: monthInfo ? monthInfo.month : null, year: monthInfo ? monthInfo.year : null }
      );

      var scopeParts = [];
      if (bcode) scopeParts.push('B.CODE ' + bcode);
      if (monthInfo) scopeParts.push(monthInfo.year ? monthLabel(monthInfo.year, monthInfo.month) : (MONTH_NAMES[monthInfo.month-1] + ' (any year)'));
      var scope = scopeParts.length ? (' for ' + scopeParts.join(', ')) : ' (all records)';

      var line = block.name + ' \u2014 by ' + colLabel + scope + ': ' + res.count.toLocaleString() + (res.count === 1 ? ' record' : ' records');
      if (res.amountSum != null) line += ', total \u20b9' + Math.round(res.amountSum).toLocaleString();
      if (bcode){
        var exists = block.dataRows.some(function(r){ return r[block.bcodeIdx] != null && String(r[block.bcodeIdx]).trim() === bcode; });
        if (!exists) line += ' (B.CODE ' + bcode + ' does not appear in this sheet at all)';
      }
      lines.push({ type: 'text', text: line });
    });

    return lines;
  }

  /* ---------- Table rendering ---------- */
  function renderTable(pivot){
    var wrap = document.createElement('div');
    wrap.className = 'table-wrap';
    var table = document.createElement('table');
    table.className = 'report-table';

    var thead = document.createElement('thead');
    var htr = document.createElement('tr');
    pivot.headers.forEach(function(h, i){
      var th = document.createElement('th');
      th.textContent = h;
      if (i === 0) th.className = 'col-bcode';
      else if (i === 1) th.className = 'col-branch';
      else if (i === pivot.headers.length - 1) th.className = 'num total-col';
      else th.className = 'num';
      htr.appendChild(th);
    });
    thead.appendChild(htr);
    table.appendChild(thead);

    var tbody = document.createElement('tbody');
    pivot.rows.forEach(function(line){
      var tr = document.createElement('tr');
      line.forEach(function(val, i){
        var td = document.createElement('td');
        td.textContent = val;
        if (i === 0) td.className = 'col-bcode';
        else if (i === 1) td.className = 'col-branch';
        else if (i === line.length - 1) td.className = 'num total-col';
        else td.className = 'num';
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);

    var tfoot = document.createElement('tfoot');
    var ftr = document.createElement('tr');
    pivot.totalRow.forEach(function(val, i){
      var td = document.createElement('td');
      td.textContent = val;
      if (i === 0) td.className = 'col-bcode';
      else if (i === 1) td.className = 'col-branch';
      else if (i === pivot.totalRow.length - 1) td.className = 'num total-col';
      else td.className = 'num';
      ftr.appendChild(td);
    });
    tfoot.appendChild(ftr);
    table.appendChild(tfoot);

    wrap.appendChild(table);
    return wrap;
  }

  /* ---------- Excel export ---------- */
  function sanitizeFilename(name){
    return String(name).replace(/[^a-z0-9\-]+/gi, '_').replace(/^_+|_+$/g, '') || 'report';
  }

  function exportPivotToExcel(pivot, sheetLabel, downloadBtn, fallbackBox){
    var aoa = [pivot.headers].concat(pivot.rows).concat([pivot.totalRow]);
    var filename = sanitizeFilename(sheetLabel) + '_MonthWise_Report.xlsx';
    downloadAoa(aoa, filename, downloadBtn, fallbackBox);
  }

  function tryBrowserDownload(blob, filename){
    try{
      var url = URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = url;
      a.download = filename;
      a.style.display = 'none';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(function(){ URL.revokeObjectURL(url); }, 4000);
      return true;
    }catch(e){
      return false;
    }
  }

  function downloadAoa(aoa, filename, downloadBtn, fallbackBox){
    var ws = XLSX.utils.aoa_to_sheet(aoa);
    var wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Report');
    var wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    var blob = new Blob([wbout], { type: 'application/octet-stream' });

    var originalLabel = downloadBtn.textContent;
    downloadBtn.disabled = true;
    downloadBtn.textContent = 'Preparing…';

    function finish(){
      downloadBtn.disabled = false;
      downloadBtn.textContent = originalLabel;
    }

    downloadsPromise.then(function(downloads){
      if (downloads){
        downloads.save({ filename: filename, data: blob }).then(finish).catch(function(err){
          finish();
          if (err && err.code === 'declined'){ return; }
          if (!tryBrowserDownload(blob, filename)) showFallback(fallbackBox, aoa);
        });
        return;
      }
      // Not running inside the claude.ai artifact runtime (e.g. opened as a
      // standalone/downloaded file) — a normal browser download works fine here.
      var ok = tryBrowserDownload(blob, filename);
      finish();
      if (!ok) showFallback(fallbackBox, aoa);
    });
  }

  function downloadMultiSheet(sheets, filename, downloadBtn, fallbackBox){
    // sheets: [{ name, aoa }, ...] — writes one workbook with multiple tabs.
    var wb = XLSX.utils.book_new();
    sheets.forEach(function(s){
      var ws = XLSX.utils.aoa_to_sheet(s.aoa);
      XLSX.utils.book_append_sheet(wb, ws, s.name);
    });
    var wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    var blob = new Blob([wbout], { type: 'application/octet-stream' });

    var originalLabel = downloadBtn.textContent;
    downloadBtn.disabled = true;
    downloadBtn.textContent = 'Preparing…';

    function finish(){
      downloadBtn.disabled = false;
      downloadBtn.textContent = originalLabel;
    }

    downloadsPromise.then(function(downloads){
      if (downloads){
        downloads.save({ filename: filename, data: blob }).then(finish).catch(function(err){
          finish();
          if (err && err.code === 'declined'){ return; }
          if (!tryBrowserDownload(blob, filename)) showFallback(fallbackBox, sheets[0].aoa);
        });
        return;
      }
      var ok = tryBrowserDownload(blob, filename);
      finish();
      if (!ok) showFallback(fallbackBox, sheets[0].aoa);
    });
  }

  function showFallback(fallbackBox, aoa){
    fallbackBox.innerHTML = '';
    var p = document.createElement('p');
    p.textContent = "Download isn't available in this view — select all in the box below and paste into Excel.";
    var ta = document.createElement('textarea');
    ta.readOnly = true;
    ta.value = aoa.map(function(line){ return line.join('\t'); }).join('\n');
    fallbackBox.appendChild(p);
    fallbackBox.appendChild(ta);
    fallbackBox.hidden = false;
    ta.focus();
    ta.select();
  }

  /* ---------- ToPay report generator: styled .xlsx download (ExcelJS) ----------
     SheetJS (used elsewhere in this file for reading uploaded workbooks) can't
     write cell colors in its free/community build, so the downloaded report is
     built with ExcelJS instead, which supports real fills/fonts. Colors mirror
     the on-screen table's palette:
       - No CHLN/DDR ref rows are left OUT of the main "Report" sheet entirely
         and appear only in "No CHLN-DDR Ref" (tinted red throughout).
       - Branch-not-in-master rows stay in "Report" but are tinted amber.
       - The REMARK column is never written to (kept blank) — color and sheet
         placement carry the meaning instead of text.
       - A final "Summary" sheet lists every flagged CN with its issue. */
  var TOPAY_XLSX_COLORS = {
    headerBg: 'FF13233D', headerInk: 'FFF4F7FC',
    dangerSoft: 'FFFBE7E5', danger: 'FFB3261E',
    accentSoft: 'FFFBEBD2', accent: 'FFC6811E',
    zebra: 'FFF0F3F8', border: 'FFDEE3EC'
  };

  function downloadStyledTopayWorkbook(result, filename, downloadBtn, fallbackBox){
    var C = TOPAY_XLSX_COLORS;
    var headers = result.headers;
    var mainRows = result.rows.filter(function(r){ return r[4] !== 'No CHLN/DDR ref'; });
    var noRefRows = result.noRefRows || [];

    function styleHeaderRow(row){
      row.eachCell(function(cell){
        cell.font = { bold: true, color: { argb: C.headerInk } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: C.headerBg } };
      });
      row.height = 20;
    }
    function fillRow(row, argb){
      row.eachCell(function(cell){
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: argb } };
      });
    }
    function borderRow(row){
      row.eachCell(function(cell){
        cell.border = { bottom: { style: 'thin', color: { argb: C.border } } };
      });
    }
    function autoWidth(ws){
      ws.columns.forEach(function(col, i){
        var len = headers[i] ? String(headers[i]).length : 10;
        col.width = Math.min(Math.max(len + 2, 10), 30);
      });
    }

    function addDataSheet(wb, name, rows, uniformFill){
      var ws = wb.addWorksheet(name);
      styleHeaderRow(ws.addRow(headers));
      autoWidth(ws);
      rows.forEach(function(line, idx){
        var display = line.slice();
        display[4] = ''; // never write the text flag
        var row = ws.addRow(display);
        row.getCell(2).font = { color: { argb: 'FF0066B3' }, bold: true };  // BRANCH
        row.getCell(3).font = { color: { argb: 'FFED1C24' }, bold: true };  // REGION
        if (uniformFill) fillRow(row, uniformFill);
        else if (line[4] === 'Branch not in master') fillRow(row, C.accentSoft);
        else if (idx % 2 === 1) fillRow(row, C.zebra);
        borderRow(row);
      });
      ws.views = [{ state: 'frozen', ySplit: 1 }];
      return ws;
    }

    function addSummarySheet(wb){
      var ws = wb.addWorksheet('Summary');
      ws.getColumn(1).width = 40; ws.getColumn(2).width = 16; ws.getColumn(3).width = 26;
      var title = ws.addRow(['ToPay Report — Summary']);
      title.font = { bold: true, size: 14 };
      ws.addRow([]);
      [
        ['Total rows fetched', result.totalRaw],
        ['Rows in Report sheet', mainRows.length],
        ['No CHLN/DDR ref (see "No CHLN-DDR Ref" sheet)', result.droppedNoRef || 0],
        ['Branch not in master (highlighted in Report sheet)', result.notFoundInMaster || 0]
      ].forEach(function(r){
        var row = ws.addRow(r);
        row.getCell(2).font = { bold: true };
      });
      ws.addRow([]);

      var issues = result.rows.filter(function(r){ return r[4]; });
      if (issues.length){
        styleHeaderRow(ws.addRow(['CN NO', 'B.CODE', 'ISSUE']));
        issues.forEach(function(r){
          var row = ws.addRow([r[3], r[0], r[4]]);
          var isNoRef = r[4] === 'No CHLN/DDR ref';
          fillRow(row, isNoRef ? C.dangerSoft : C.accentSoft);
          row.getCell(3).font = { bold: true, color: { argb: isNoRef ? C.danger : C.accent } };
          borderRow(row);
        });
      }
    }

    var originalLabel = downloadBtn.textContent;
    downloadBtn.disabled = true;
    downloadBtn.textContent = 'Preparing…';
    function finish(){
      downloadBtn.disabled = false;
      downloadBtn.textContent = originalLabel;
    }

    var wb = new ExcelJS.Workbook();
    addDataSheet(wb, 'Report', mainRows);
    if (noRefRows.length) addDataSheet(wb, 'No CHLN-DDR Ref', noRefRows, C.dangerSoft);
    addSummarySheet(wb);

    wb.xlsx.writeBuffer().then(function(buffer){
      var blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      downloadsPromise.then(function(downloads){
        if (downloads){
          downloads.save({ filename: filename, data: blob }).then(finish).catch(function(err){
            finish();
            if (err && err.code === 'declined'){ return; }
            if (!tryBrowserDownload(blob, filename)) showFallback(fallbackBox, [headers].concat(mainRows));
          });
          return;
        }
        var ok = tryBrowserDownload(blob, filename);
        finish();
        if (!ok) showFallback(fallbackBox, [headers].concat(mainRows));
      });
    }).catch(function(err){
      finish();
      showFallback(fallbackBox, [headers].concat(mainRows));
    });
  }

  /* ---------- Region-wise report: split any sheet by its REGION column ---------- */
  var regionState = null; // { headerRow, baseName, groups: [{ key, display, rows }] }

  function stripExt(name){
    return String(name).replace(/\.[^.]+$/, '');
  }

  function groupRowsByRegion(headerRow, dataRows){
    var regionIdx = findColIndex(headerRow, 'REGION');
    if (regionIdx === -1) return { error: 'No REGION column found in this file. Add a REGION column (like in the example sheet) and try again.' };
    var map = {};
    var order = [];
    dataRows.forEach(function(row){
      var raw = row[regionIdx];
      var display = (raw == null || String(raw).trim() === '') ? '(BLANK)' : String(raw).trim();
      var key = display.toUpperCase();
      if (!map[key]){
        map[key] = { key: key, display: display, rows: [] };
        order.push(key);
      }
      map[key].rows.push(row);
    });
    order.sort(function(a, b){ return map[a].display.localeCompare(map[b].display); });
    return { groups: order.map(function(k){ return map[k]; }) };
  }

  function renderRegionList(groups, totalRows){
    var wrap = document.createElement('div');
    wrap.className = 'table-wrap';
    var table = document.createElement('table');
    table.className = 'report-table';

    var thead = document.createElement('thead');
    var htr = document.createElement('tr');
    ['REGION', 'RECORDS', 'FILE'].forEach(function(h, i){
      var th = document.createElement('th');
      th.textContent = h;
      th.className = (i === 0) ? 'col-branch' : 'num';
      htr.appendChild(th);
    });
    thead.appendChild(htr);
    table.appendChild(thead);

    var tbody = document.createElement('tbody');
    groups.forEach(function(g){
      var tr = document.createElement('tr');
      var tdName = document.createElement('td');
      tdName.textContent = g.display;
      tdName.className = 'col-branch';
      var tdCount = document.createElement('td');
      tdCount.textContent = g.rows.length;
      tdCount.className = 'num';
      var tdFile = document.createElement('td');
      tdFile.textContent = sanitizeFilename(g.display) + '.xlsx';
      tdFile.className = 'num';
      tr.appendChild(tdName);
      tr.appendChild(tdCount);
      tr.appendChild(tdFile);
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);

    var tfoot = document.createElement('tfoot');
    var ftr = document.createElement('tr');
    var tdLabel = document.createElement('td');
    tdLabel.textContent = 'TOTAL';
    tdLabel.className = 'col-branch';
    var tdTotal = document.createElement('td');
    tdTotal.textContent = totalRows;
    tdTotal.className = 'num total-col';
    var tdBlank = document.createElement('td');
    tdBlank.className = 'num total-col';
    ftr.appendChild(tdLabel);
    ftr.appendChild(tdTotal);
    ftr.appendChild(tdBlank);
    tfoot.appendChild(ftr);
    table.appendChild(tfoot);

    wrap.appendChild(table);
    return wrap;
  }

  function processRegionWorkbook(workbook, displayName){
    var pageError = document.getElementById('regionPageError');
    var card = document.getElementById('regionCard');
    var slot = document.getElementById('regionListSlot');
    var summary = document.getElementById('regionSummary');
    pageError.hidden = true;
    card.hidden = true;
    slot.innerHTML = '';

    var sheetName = workbook.SheetNames[0];
    var sheet = workbook.Sheets[sheetName];
    var rows2d = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null, blankrows: false });
    if (!rows2d.length){
      pageError.textContent = 'This file looks empty.';
      pageError.hidden = false;
      regionState = null;
      return;
    }
    var headerRow = rows2d[0];
    var dataRows = rows2d.slice(1);
    var grouped = groupRowsByRegion(headerRow, dataRows);
    if (grouped.error){
      pageError.textContent = grouped.error;
      pageError.hidden = false;
      regionState = null;
      return;
    }

    regionState = { headerRow: headerRow, baseName: stripExt(displayName), groups: grouped.groups };
    summary.textContent = grouped.groups.length + ' region' + (grouped.groups.length === 1 ? '' : 's') + ' found across ' + dataRows.length + ' records. Each region becomes its own Excel file inside the ZIP.';
    slot.appendChild(renderRegionList(grouped.groups, dataRows.length));
    card.hidden = false;
  }

  function handleRegionFile(file){
    var pageError = document.getElementById('regionPageError');
    var fileMeta = document.getElementById('regionFileMeta');
    pageError.hidden = true;

    var reader = new FileReader();
    reader.onload = function(e){
      try{
        var data = new Uint8Array(e.target.result);
        var workbook = XLSX.read(data, { type: 'array', cellDates: true });
        fileMeta.hidden = false;
        fileMeta.innerHTML = '';
        var strong = document.createElement('strong');
        strong.textContent = file.name;
        fileMeta.appendChild(document.createTextNode('Loaded '));
        fileMeta.appendChild(strong);
        processRegionWorkbook(workbook, file.name);
      }catch(err){
        pageError.textContent = "Couldn't read this file. Make sure it's a valid .xlsx, .xls or .csv export. (" + (err && err.message ? err.message : 'unknown error') + ')';
        pageError.hidden = false;
      }
    };
    reader.onerror = function(){
      pageError.textContent = "Couldn't read this file from disk. Please try again.";
      pageError.hidden = false;
    };
    reader.readAsArrayBuffer(file);
  }

  function downloadRegionZip(){
    if (!regionState || !regionState.groups.length) return;
    var downloadBtn = document.getElementById('regionDownloadBtn');
    var fallbackBox = document.getElementById('regionFallback');
    var originalLabel = downloadBtn.innerHTML;
    downloadBtn.disabled = true;
    downloadBtn.querySelector('span').textContent = 'Preparing…';

    function finish(){
      downloadBtn.disabled = false;
      downloadBtn.innerHTML = originalLabel;
    }

    try{
      var zip = new JSZip();
      var usedNames = {};
      regionState.groups.forEach(function(g){
        var wb = XLSX.utils.book_new();
        var ws = XLSX.utils.aoa_to_sheet([regionState.headerRow].concat(g.rows));
        XLSX.utils.book_append_sheet(wb, ws, 'Sheet1');
        var arr = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        var base = sanitizeFilename(g.display);
        var name = base;
        var n = 1;
        while (usedNames[name]){ name = base + '_' + (++n); }
        usedNames[name] = true;
        zip.file(name + '.xlsx', arr);
      });

      zip.generateAsync({ type: 'blob' }).then(function(blob){
        var filename = sanitizeFilename(regionState.baseName) + '_REGION_WISE.zip';
        downloadsPromise.then(function(downloads){
          if (downloads){
            downloads.save({ filename: filename, data: blob }).then(finish).catch(function(err){
              finish();
              if (err && err.code === 'declined'){ return; }
              if (!tryBrowserDownload(blob, filename)){
                fallbackBox.hidden = false;
                fallbackBox.textContent = "Download isn't available in this view. Please try again in a regular browser tab.";
              }
            });
            return;
          }
          var ok = tryBrowserDownload(blob, filename);
          finish();
          if (!ok){
            fallbackBox.hidden = false;
            fallbackBox.textContent = "Download isn't available in this view. Please try again in a regular browser tab.";
          }
        });
      }).catch(function(err){
        finish();
        fallbackBox.hidden = false;
        fallbackBox.textContent = 'Could not build the ZIP file. (' + (err && err.message ? err.message : 'unknown error') + ')';
      });
    }catch(err){
      finish();
      fallbackBox.hidden = false;
      fallbackBox.textContent = 'Could not build the ZIP file. (' + (err && err.message ? err.message : 'unknown error') + ')';
    }
  }

  /* ---------- Auto Mail (Region-wise): directory parsing + recipient classification ---------- */
  var automailState = null; // { regions: [{ region, branches: [{code,name,recipients:[...]}], regionDbp: [...] }], unknown: [...] }
  var topayGenLastResult = null;   // the most recently generated/fetched ToPay report, used as the source for per-region email attachments
  var topayGenLastSourceName = '';
  var paidGenLastResult = null;    // the most recently generated Paid report
  var paidGenLastSourceName = '';
  var lastPaidRawSheet = null;     // { headerRow, dataRows, name } of the last raw Paid file loaded, for re-processing after a master update
  var comboPaidResult = null, comboPaidName = '';   // generated Paid result for the combined Paid+ToPay download
  var comboTopayResult = null, comboTopayName = ''; // generated ToPay result for the combined Paid+ToPay download

  var AUTOMAIL_SUBJECT_TEMPLATE = '{REGION} Region \u2013 ToPay Unbilled Report';
  var AUTOMAIL_BODY_TEMPLATE = [
    'Dear All,',
    '',
    'Please find attached the {REGION} Region ToPay Unbilled Report.',
    '',
    'This report contains cases where delivery has already been completed but the bill is still not generated. Requesting all concerned branch teams to please check the pending cases related to their respective branches and take the necessary action on priority.',
    '',
    'Also, some of the dockets in the report are related to TBB parties but are currently showing as ToPay. Kindly check such cases and, wherever applicable, get the docket modified from ToPay to TBB so the pending case can be cleared and billing completed.',
    '',
    'If there is any issue related to bill generation, rate, documentation, TBB/ToPay modification, or any other billing-related matter, please discuss it with me so I can check and resolve it accordingly.',
    '',
    'Requesting all concerned branch teams to kindly review their pending cases and ensure the report is cleared at the earliest.',
    '',
    'Your support and timely action will be appreciated.',
    '',
    'Thanks & Regards,',
    'Aditya Sharma',
    'Contact-9667391193',
    'Emp Code- 39942'
  ].join('\n');

  function fillTemplate(tpl, region){
    return tpl.replace(/\{REGION\}/g, region);
  }

  function getRegionReportRows(regionDisplay){
    if (!topayGenLastResult || !topayGenLastResult.rows) return null;
    var key = String(regionDisplay || '').trim().toUpperCase();
    return topayGenLastResult.rows.filter(function(r){
      return String(r[2] == null ? '' : r[2]).trim().toUpperCase() === key;
    });
  }

  function buildMailtoUrl(opts){
    // opts: { to: [emails], cc: [emails], subject, body }
    var params = [];
    if (opts.cc && opts.cc.length) params.push('cc=' + encodeURIComponent(opts.cc.join(',')));
    params.push('subject=' + encodeURIComponent(opts.subject || ''));
    params.push('body=' + encodeURIComponent(opts.body || ''));
    var toPart = (opts.to || []).join(',');
    var full = 'mailto:' + toPart + '?' + params.join('&');
    // A very long mailto URL silently fails or truncates on many OS/browser
    // combinations (commonly somewhere past ~1800-2000 characters). If a full
    // recipient list would push past that, drop the To: list from the link —
    // the "Copy emails" button still has the complete list to paste in by hand —
    // rather than ship a link that looks right but loses recipients silently.
    if (full.length > 1800 && toPart){
      var noTo = 'mailto:?' + params.join('&');
      return { url: noTo, toDropped: true, toCount: (opts.to || []).length };
    }
    return { url: full, toDropped: false, toCount: (opts.to || []).length };
  }

  function regionRecipientEmails(entry){
    var emails = {};
    entry.branches.forEach(function(br){ br.recipients.forEach(function(r){ if (r.email) emails[r.email.toLowerCase()] = r.email; }); });
    entry.regionDbp.forEach(function(r){ if (r.email) emails[r.email.toLowerCase()] = r.email; });
    return Object.keys(emails).map(function(k){ return emails[k]; });
  }

  var AUTOMAIL_DESIG_COL = 5; // DESIGNATION column in the directory sheet
  var AUTOMAIL_NAME_COL = 4;  // OFFICIAL (name) column
  var AUTOMAIL_CONTACT_COL = 7;
  var AUTOMAIL_EMAIL_COL = 8;
  var AUTOMAIL_STATEBRANCH_COL = 0;
  var AUTOMAIL_CODE_COL = 1;

  function isPositiveIntLike(v){
    if (v === null || v === undefined || v === '') return false;
    var n = Number(v);
    return !isNaN(n) && n > 0;
  }

  function classifyDesignation(desigRaw){
    var d = String(desigRaw || '').toUpperCase();
    if (d.indexOf('AREA') !== -1 && d.indexOf('MANAG') !== -1) return 'EXCLUDED';
    if (d.indexOf('BRANCH') !== -1 && d.indexOf('INCHARGE') !== -1) return 'INCHARGE';
    if (d.indexOf('BRANCH') !== -1 && d.indexOf('MANAGER') !== -1) return 'MANAGER';
    if (d.indexOf('DBP') !== -1) return 'DBP';
    if (d.indexOf('BILLING') !== -1) return 'BILLING';
    return 'OTHER';
  }

  var AUTOMAIL_ROLE_LABEL = { INCHARGE: 'Branch Incharge', MANAGER: 'Branch Manager', BILLING: 'Billing', DBP: 'DBP', OTHER: 'Other Staff' };

  function parseDirectorySheet(sheet){
    var rows2d = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null, blankrows: false });
    var branches = [];
    var cur = null;
    for (var i = 0; i < rows2d.length; i++){
      var r = rows2d[i];
      var code = r[AUTOMAIL_CODE_COL];
      var name = r[AUTOMAIL_NAME_COL];
      var desig = r[AUTOMAIL_DESIG_COL];
      if (isPositiveIntLike(code)){
        cur = { branchCode: Math.round(Number(code)), branchName: (r[AUTOMAIL_STATEBRANCH_COL] || '').toString().trim(), employees: [] };
        branches.push(cur);
      }
      if (cur && (name || desig)){
        cur.employees.push({
          name: (name || '').toString().trim(),
          desig: (desig || '').toString().trim(),
          contact: r[AUTOMAIL_CONTACT_COL] == null ? '' : String(r[AUTOMAIL_CONTACT_COL]).trim(),
          email: (r[AUTOMAIL_EMAIL_COL] || '').toString().trim()
        });
      }
    }
    return branches;
  }

  function buildAutomailRegions(branches){
    var regionMap = {}; // region -> { region, branches: [...] }
    var order = [];
    branches.forEach(function(b){
      var master = branchMaster.get(b.branchCode);
      var region = master ? master.region : 'UNKNOWN / NOT IN BRANCH MASTER';
      var branchName = (master && master.branch) ? master.branch : (b.branchName || ('CODE ' + b.branchCode));
      if (!regionMap[region]){ regionMap[region] = { region: region, branches: [] }; order.push(region); }

      var recipients = []; // { role, name, desig, email, contact }
      var hasManager = false, hasBilling = false;
      var candidateOthers = [];
      b.employees.forEach(function(e){
        if (!e.email && !e.name) return;
        var role = classifyDesignation(e.desig);
        if (role === 'EXCLUDED') return;
        if (role === 'OTHER'){ candidateOthers.push(e); return; }
        if (role === 'MANAGER') hasManager = true;
        if (role === 'BILLING') hasBilling = true;
        recipients.push({ role: role, name: e.name, desig: e.desig, email: e.email, contact: e.contact });
      });
      if (!hasManager && !hasBilling){
        candidateOthers.forEach(function(e){
          recipients.push({ role: 'OTHER', name: e.name, desig: e.desig, email: e.email, contact: e.contact });
        });
      }
      regionMap[region].branches.push({ code: b.branchCode, name: branchName, recipients: recipients });
    });

    order.sort(function(a, b2){ if (a === 'UNKNOWN / NOT IN BRANCH MASTER') return 1; if (b2 === 'UNKNOWN / NOT IN BRANCH MASTER') return -1; return a.localeCompare(b2); });

    return order.map(function(region){
      var entry = regionMap[region];
      entry.branches.sort(function(a, b2){ return a.name.localeCompare(b2.name); });
      var dbpMap = {};
      entry.branches.forEach(function(br){
        br.recipients.forEach(function(rec){
          if (rec.role === 'DBP' && rec.email){
            var key = rec.email.toLowerCase();
            if (!dbpMap[key]) dbpMap[key] = rec;
          }
        });
      });
      entry.regionDbp = Object.keys(dbpMap).map(function(k){ return dbpMap[k]; });
      return entry;
    });
  }

  function renderAutomailRegions(regions){
    var slot = document.getElementById('automailRegionsSlot');
    slot.innerHTML = '';
    regions.forEach(function(entry){
      var section = document.createElement('section');
      section.className = 'report-card';
      section.style.marginTop = '14px';

      var head = document.createElement('div');
      head.className = 'report-head';
      var titleWrap = document.createElement('div');
      var title = document.createElement('p');
      title.className = 'report-title';
      title.textContent = entry.region;
      var summary = document.createElement('p');
      summary.className = 'report-summary';
      var recipientCount = entry.branches.reduce(function(s, br){ return s + br.recipients.length; }, 0);
      summary.textContent = entry.branches.length + ' branch' + (entry.branches.length === 1 ? '' : 'es') + ' · ' + recipientCount + ' recipients · ' + entry.regionDbp.length + ' region DBP (compulsory)';
      titleWrap.appendChild(title);
      titleWrap.appendChild(summary);

      var copyBtn = document.createElement('button');
      copyBtn.type = 'button';
      copyBtn.className = 'download-btn';
      copyBtn.innerHTML = '<span>Copy emails</span>';
      copyBtn.addEventListener('click', function(){
        var emails = {};
        entry.branches.forEach(function(br){ br.recipients.forEach(function(r){ if (r.email) emails[r.email.toLowerCase()] = r.email; }); });
        entry.regionDbp.forEach(function(r){ if (r.email) emails[r.email.toLowerCase()] = r.email; });
        var list = Object.keys(emails).map(function(k){ return emails[k]; }).join('; ');
        if (navigator.clipboard && navigator.clipboard.writeText){
          navigator.clipboard.writeText(list).then(function(){
            copyBtn.querySelector('span').textContent = 'Copied!';
            setTimeout(function(){ copyBtn.querySelector('span').textContent = 'Copy emails'; }, 1500);
          });
        }
      });

      var composeBtn = document.createElement('button');
      composeBtn.type = 'button';
      composeBtn.className = 'download-btn';
      composeBtn.innerHTML = '<span>Compose email</span>';
      composeBtn.addEventListener('click', function(){
        var senderName = document.getElementById('automailSenderName').value.trim();
        var alwaysCc = document.getElementById('automailAlwaysCc').value.split(',').map(function(s){ return s.trim(); }).filter(Boolean);
        var to = regionRecipientEmails(entry);
        var mail = buildMailtoUrl({
          to: to, cc: alwaysCc,
          subject: fillTemplate(AUTOMAIL_SUBJECT_TEMPLATE, entry.region, senderName),
          body: fillTemplate(AUTOMAIL_BODY_TEMPLATE, entry.region, senderName)
        });
        if (mail.toDropped){
          alert('This region has ' + mail.toCount + ' recipients — too many to fit in a mail link reliably, so the To: field was left blank. Click "Copy emails" first, then paste them into the To: field once your mail app opens.');
        }
        window.open(mail.url, '_self');
      });

      var reportBtn = document.createElement('button');
      reportBtn.type = 'button';
      reportBtn.className = 'download-btn';
      var regionRows = getRegionReportRows(entry.region);
      reportBtn.innerHTML = '<span>Download report (.xlsx)</span>';
      reportBtn.disabled = !regionRows || !regionRows.length;
      reportBtn.addEventListener('click', function(){
        var rows = getRegionReportRows(entry.region) || [];
        var aoa = [TOPAY_GEN_OUTPUT_HEADERS].concat(rows);
        downloadAoa(aoa, sanitizeFilename(entry.region) + '_ToPay_Unbilled.xlsx', reportBtn, attachFallback);
      });

      var attachFallback = document.createElement('div');
      attachFallback.className = 'fallback-box';
      attachFallback.hidden = true;

      var btnRow = document.createElement('div');
      btnRow.style.cssText = 'display:flex;gap:.5rem;flex-wrap:wrap;';
      btnRow.appendChild(reportBtn);
      btnRow.appendChild(composeBtn);
      btnRow.appendChild(copyBtn);

      head.appendChild(titleWrap);
      head.appendChild(btnRow);
      section.appendChild(head);

      var reportNote = document.createElement('p');
      reportNote.className = 'file-meta';
      reportNote.style.marginTop = '0';
      reportNote.textContent = regionRows && regionRows.length
        ? regionRows.length.toLocaleString() + ' report rows available for this region (from ' + (topayGenLastSourceName || 'the last generated report') + ')'
        : 'No generated report loaded yet for this region — use "Generate ToPay Report" first, then come back here to attach it.';
      section.appendChild(reportNote);
      section.appendChild(attachFallback);

      if (entry.regionDbp.length){
        var dbpP = document.createElement('p');
        dbpP.className = 'file-meta';
        dbpP.style.marginTop = '0';
        dbpP.innerHTML = '<strong>Region DBP (compulsory):</strong> ' + entry.regionDbp.map(function(r){ return (r.name || r.email) + (r.email ? ' &lt;' + r.email + '&gt;' : ''); }).join(', ');
        section.appendChild(dbpP);
      }

      var wrap = document.createElement('div');
      wrap.className = 'table-wrap';
      var table = document.createElement('table');
      table.className = 'report-table';
      var thead = document.createElement('thead');
      var htr = document.createElement('tr');
      ['BRANCH', 'ROLE', 'NAME', 'DESIGNATION', 'EMAIL'].forEach(function(h, i){
        var th = document.createElement('th');
        th.textContent = h;
        th.className = (i === 0 || i === 2 || i === 3 || i === 4) ? 'col-branch' : 'num';
        htr.appendChild(th);
      });
      thead.appendChild(htr);
      table.appendChild(thead);
      var tbody = document.createElement('tbody');
      entry.branches.forEach(function(br){
        if (!br.recipients.length){
          var trEmpty = document.createElement('tr');
          var tdB = document.createElement('td'); tdB.textContent = br.name + ' (' + br.code + ')'; tdB.className = 'col-branch';
          var tdRest = document.createElement('td'); tdRest.colSpan = 4; tdRest.textContent = 'No matching recipient found — please review this branch manually.'; tdRest.className = 'col-branch';
          trEmpty.appendChild(tdB); trEmpty.appendChild(tdRest);
          tbody.appendChild(trEmpty);
          return;
        }
        br.recipients.forEach(function(rec, idx){
          var tr = document.createElement('tr');
          var tdBranch = document.createElement('td'); tdBranch.className = 'col-branch';
          tdBranch.textContent = idx === 0 ? (br.name + ' (' + br.code + ')') : '';
          var tdRole = document.createElement('td'); tdRole.className = 'num'; tdRole.textContent = AUTOMAIL_ROLE_LABEL[rec.role] || rec.role;
          var tdName = document.createElement('td'); tdName.className = 'col-branch'; tdName.textContent = rec.name;
          var tdDesig = document.createElement('td'); tdDesig.className = 'col-branch'; tdDesig.textContent = rec.desig;
          var tdEmail = document.createElement('td'); tdEmail.className = 'col-branch'; tdEmail.textContent = rec.email;
          tr.appendChild(tdBranch); tr.appendChild(tdRole); tr.appendChild(tdName); tr.appendChild(tdDesig); tr.appendChild(tdEmail);
          tbody.appendChild(tr);
        });
      });
      table.appendChild(tbody);
      wrap.appendChild(table);
      section.appendChild(wrap);
      slot.appendChild(section);
    });
  }

  function processAutomailWorkbook(workbook){
    var pageError = document.getElementById('automailPageError');
    var card = document.getElementById('automailCard');
    var summary = document.getElementById('automailSummary');
    pageError.hidden = true;
    card.hidden = true;

    var sheetName = workbook.SheetNames.indexOf('OLSC BRANCHES') !== -1 ? 'OLSC BRANCHES' : workbook.SheetNames[0];
    var sheet = workbook.Sheets[sheetName];
    if (!sheet){
      pageError.textContent = "Couldn't find a branch sheet in this file.";
      pageError.hidden = false;
      automailState = null;
      return;
    }
    var branches = parseDirectorySheet(sheet);
    if (!branches.length){
      pageError.textContent = "No branch/employee rows found in the '" + sheetName + "' sheet.";
      pageError.hidden = false;
      automailState = null;
      return;
    }
    loadBranchMaster();
    var regions = buildAutomailRegions(branches);
    automailState = { regions: regions, sheetUsed: sheetName };

    var totalRecipients = regions.reduce(function(s, r){ return s + r.branches.reduce(function(s2, br){ return s2 + br.recipients.length; }, 0); }, 0);
    var unknownRegion = regions.filter(function(r){ return r.region === 'UNKNOWN / NOT IN BRANCH MASTER'; })[0];
    summary.textContent = regions.length + ' regions, ' + branches.length + ' branches, ' + totalRecipients + ' recipients found (read from "' + sheetName + '")' + (unknownRegion ? ' — ' + unknownRegion.branches.length + ' branches could not be matched to a region.' : '') + '.';
    renderAutomailRegions(regions);
    card.hidden = false;
  }

  function handleAutomailFile(file){
    var pageError = document.getElementById('automailPageError');
    var fileMeta = document.getElementById('automailFileMeta');
    pageError.hidden = true;
    var reader = new FileReader();
    reader.onload = function(e){
      try{
        var data = new Uint8Array(e.target.result);
        var workbook = XLSX.read(data, { type: 'array', cellDates: true });
        fileMeta.hidden = false;
        fileMeta.innerHTML = '';
        var strong = document.createElement('strong');
        strong.textContent = file.name;
        fileMeta.appendChild(document.createTextNode('Loaded '));
        fileMeta.appendChild(strong);
        processAutomailWorkbook(workbook);
      }catch(err){
        pageError.textContent = "Couldn't read this file. (" + (err && err.message ? err.message : 'unknown error') + ')';
        pageError.hidden = false;
      }
    };
    reader.onerror = function(){
      pageError.textContent = "Couldn't read this file from disk. Please try again.";
      pageError.hidden = false;
    };
    reader.readAsArrayBuffer(file);
  }

  function downloadAutomailCsv(){
    if (!automailState || !automailState.regions.length) return;
    var lines = [['REGION', 'BRANCH CODE', 'BRANCH', 'ROLE', 'NAME', 'DESIGNATION', 'CONTACT', 'EMAIL']];
    automailState.regions.forEach(function(entry){
      entry.branches.forEach(function(br){
        br.recipients.forEach(function(rec){
          lines.push([entry.region, br.code, br.name, AUTOMAIL_ROLE_LABEL[rec.role] || rec.role, rec.name, rec.desig, rec.contact, rec.email]);
        });
      });
    });
    var csv = lines.map(function(row){
      return row.map(function(cell){
        var s = cell == null ? '' : String(cell);
        if (s.indexOf(',') !== -1 || s.indexOf('"') !== -1 || s.indexOf('\n') !== -1){
          s = '"' + s.replace(/"/g, '""') + '"';
        }
        return s;
      }).join(',');
    }).join('\r\n');
    var blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8' });
    var filename = 'AUTOMAIL_RECIPIENTS_REGION_WISE.csv';
    downloadsPromise.then(function(downloads){
      if (downloads){
        downloads.save({ filename: filename, data: blob }).catch(function(){ tryBrowserDownload(blob, filename); });
        return;
      }
      tryBrowserDownload(blob, filename);
    });
  }

  /* ---------- ToPay report generator: transform logic ---------- */
  var TOPAY_GEN_OUTPUT_HEADERS = [
    'B.CODE','BRANCH','REGION','CN NO','REMARK','CN_DATE','FROMSOURCE','TODIST','CNR','CEE',
    'CN_PKG','CN_ACTUAL_WEIGHT','FRIGHT_MODE','DELIVERY_DATE','CN_DDR_NO','CN_ADR_NO','CN_ADR_DATE',
    'CN_AMOUNT','TPTR_MODE','LOAD_TYPE','CHLN_CHLN_NO','CHLN_LORRY_NO','VFG'
  ];

  function truthyNum(v){
    if (v === null || v === undefined || v === '') return false;
    var n = typeof v === 'number' ? v : parseFloat(v);
    return !isNaN(n) && n !== 0;
  }

  function controllingBranchOf(code){
    var primary = branchMaster.get(code);
    if (primary && primary.controllingBranch != null) return primary.controllingBranch;
    var fb = branchFallback.get(code);
    if (fb && fb.controllingBranch != null) return fb.controllingBranch;
    return null;
  }

  function resolveFinalBranch(rawBcode){
    var code = rawBcode;
    // A code below 5000 is already a real branch code (this is exactly what a
    // CHLN/DDR number's leading digits identify) — look it up directly, with no
    // redirect/hop, even when it isn't found in the master. Redirecting a real
    // branch code would silently substitute a different branch's name.
    if (code < 5000){
      return { bcode: code, entry: branchMaster.get(code) || null };
    }
    // 5000+ is always a PDA/sub-delivery/retail code, never a real terminal branch —
    // it must be redirected to its controlling branch at least once, even when it
    // already has its own (incomplete) row in the master. Keep hopping through the
    // controlling-branch chain (primary master first, then the fallback file) while
    // the resolved code is itself still >=5000; stop as soon as it drops below 5000
    // or no further controlling branch can be found.
    var hops = 0;
    while (code >= 5000 && hops < 5){
      var ctrl = controllingBranchOf(code);
      if (ctrl == null || ctrl === code) break;
      code = ctrl;
      hops++;
    }
    var entry = branchMaster.get(code);
    return { bcode: code, entry: entry || null };
  }

  function deriveRefBranchCode(ref){
    var n = typeof ref === 'number' ? ref : parseFloat(ref);
    if (!isFinite(n) || n <= 0) return null;
    var s = String(Math.trunc(n));
    var blen = s.length - 10;
    if (blen < 2 || blen > 5) return null;
    return parseInt(s.slice(0, blen), 10);
  }

  function generateTopayReport(headerRow, dataRows){
    var col = {
      cnCnNo: findColIndex(headerRow, 'CNCNNO'),
      cnDate: findColIndex(headerRow, 'CNDATE'),
      fromSource: findColIndex(headerRow, 'FROMSOURCE'),
      toDist: findColIndex(headerRow, 'TODIST'),
      cnr: findColIndex(headerRow, 'CNR'),
      cee: findColIndex(headerRow, 'CEE'),
      cnPkg: findColIndex(headerRow, 'CNPKG'),
      cnWeight: findColIndex(headerRow, 'CNACTUALWEIGHT'),
      frightMode: findColIndex(headerRow, 'FRIGHTMODE'),
      deliveryDate: findColIndex(headerRow, 'DELIVERYDATE'),
      cnDdrNo: findColIndex(headerRow, 'CNDDRNO'),
      cnAdrNo: findColIndex(headerRow, 'CNADRNO'),
      cnAdrDate: findColIndex(headerRow, 'CNADRDATE'),
      cnManualCnNo: findColIndex(headerRow, 'CNMANUALCNNO'),
      cnAmount: findColIndex(headerRow, 'CNAMOUNT'),
      tptrMode: findColIndex(headerRow, 'TPTRMODE'),
      loadType: findColIndex(headerRow, 'LOADTYPE'),
      chlnChlnNo: findColIndex(headerRow, 'CHLNCHLNNO'),
      chlnLorryNo: findColIndex(headerRow, 'CHLNLORRYNO'),
      verifiedFlg: findColIndex(headerRow, 'VERIFIEDFLG')
    };

    if (col.cnCnNo === -1 || (col.chlnChlnNo === -1 && col.cnDdrNo === -1)){
      var missing = [];
      if (col.cnCnNo === -1) missing.push('CN_CN_NO');
      if (col.chlnChlnNo === -1 && col.cnDdrNo === -1) missing.push('CHLN_CHLN_NO or CN_DDR_NO');
      return { error: "This file is missing " + missing.join(' and ') + ". Columns found: " + headerRow.filter(Boolean).join(', ') };
    }

    var rows = [];
    var noRefRows = [];
    var droppedNoRef = 0, notFoundInMaster = 0;

    dataRows.forEach(function(row){
      var chln = col.chlnChlnNo >= 0 ? row[col.chlnChlnNo] : null;
      var ddr = col.cnDdrNo >= 0 ? row[col.cnDdrNo] : null;
      var ref = truthyNum(chln) ? chln : ddr;

      var finalBcode = '', branchName = '', regionName = '', remark = '';
      var rawBcode = truthyNum(ref) ? deriveRefBranchCode(ref) : null;
      var hasRef = rawBcode !== null;

      if (hasRef){
        var resolved = resolveFinalBranch(rawBcode);
        finalBcode = resolved.bcode;
        branchName = resolved.entry ? resolved.entry.branch : '';
        regionName = resolved.entry ? resolved.entry.region : '';
        if (!resolved.entry){
          notFoundInMaster++;
          remark = 'Branch not in master';
        }
      } else {
        // No CHLN or DDR number to derive a branch from — keep the row anyway
        // (blank B.CODE/BRANCH/REGION) instead of silently dropping it.
        droppedNoRef++;
        remark = 'No CHLN/DDR ref';
      }

      var manualCnNo = col.cnManualCnNo >= 0 ? row[col.cnManualCnNo] : null;
      var cnNo = truthyNum(manualCnNo) ? manualCnNo : row[col.cnCnNo];

      var get = function(idx){ return idx >= 0 ? row[idx] : null; };

      var outRow = [
        finalBcode, branchName, regionName, cnNo, remark,
        get(col.cnDate), get(col.fromSource), get(col.toDist), get(col.cnr), get(col.cee),
        get(col.cnPkg), get(col.cnWeight), get(col.frightMode), get(col.deliveryDate),
        get(col.cnDdrNo), get(col.cnAdrNo), get(col.cnAdrDate),
        get(col.cnAmount), get(col.tptrMode), get(col.loadType),
        chln, get(col.chlnLorryNo), get(col.verifiedFlg)
      ];

      rows.push(outRow);
      if (!hasRef) noRefRows.push(outRow);
    });

    rows.sort(function(a, b){
      var an = (typeof a[0] === 'number') ? a[0] : Infinity;
      var bn = (typeof b[0] === 'number') ? b[0] : Infinity;
      return an - bn; // stable in modern JS engines; blanks sort last
    });

    return {
      headers: TOPAY_GEN_OUTPUT_HEADERS, rows: rows, noRefRows: noRefRows,
      totalRaw: dataRows.length, kept: rows.length,
      droppedNoRef: droppedNoRef, notFoundInMaster: notFoundInMaster
    };
  }

  /* ---------- Paid report generator: transform logic ----------
     B.CODE here isn't looked up from a CHLN/DDR reference like ToPay — it's
     decoded straight out of the CN number itself. A raw CN_CN_NO is
     <B.CODE><2-digit year><7-digit serial>, e.g. 102261009156 -> B.CODE 102,
     year 26, serial 1009156; or 1001261027525 -> B.CODE 1001. So the branch
     code is just everything before the trailing 9 digits. Once we have that
     numeric code, it's fed through the exact same resolveFinalBranch() used
     for ToPay, so 5000+ PDA codes hop to their controlling branch the same way. */
  var PAID_GEN_OUTPUT_HEADERS = [
    'B.CODE','BRANCH','REGION','CN NO','REMARK','CN_DATE','Customer_Type','FROMSOURCE','TODIST','CNR','CEE',
    'PARTY CODE','PARTY NAME','CN_PKG','CN_ACTUAL_WEIGHT','FRIGHT_MODE','DELIVERY_DATE','CN_DDR_NO','CN_ADR_NO',
    'CN_ADR_DATE','CN_AMOUNT','TPTR_MODE','LOAD_TYPE','VFG','STOP_AUTO_BILLING'
  ];

  function deriveBcodeFromCnNo(raw){
    if (raw === null || raw === undefined || raw === '') return null;
    var s = String(typeof raw === 'number' ? Math.trunc(raw) : raw).trim();
    if (!/^[0-9]+$/.test(s)) return null;   // a manual/alpha CN number doesn't follow this pattern
    var blen = s.length - 9;                // trailing 9 digits = 2-digit year + 7-digit serial
    if (blen < 2 || blen > 5) return null;
    var n = parseInt(s.slice(0, blen), 10);
    if (!isFinite(n) || n <= 0) return null;
    return n;
  }

  function generatePaidReport(headerRow, dataRows){
    var col = {
      cnCnNo: findColIndex(headerRow, 'CNCNNO'),
      cnDate: findColIndex(headerRow, 'CNDATE'),
      fromSource: findColIndex(headerRow, 'FROMSOURCE'),
      toDist: findColIndex(headerRow, 'TODIST'),
      cnr: findColIndex(headerRow, 'CNR'),
      cee: findColIndex(headerRow, 'CEE'),
      billingPartyCode: findColIndex(headerRow, 'CNBLLINGPARTYCODE') >= 0 ? findColIndex(headerRow, 'CNBLLINGPARTYCODE') : findColIndex(headerRow, 'CNBILLINGPARTYCODE'),
      billingPartyDetails: findColIndex(headerRow, 'BLLINGPARTYDETAILS') >= 0 ? findColIndex(headerRow, 'BLLINGPARTYDETAILS') : findColIndex(headerRow, 'BILLINGPARTYDETAILS'),
      cnPkg: findColIndex(headerRow, 'CNPKG'),
      cnWeight: findColIndex(headerRow, 'CNACTUALWEIGHT'),
      frightMode: findColIndex(headerRow, 'FRIGHTMODE'),
      deliveryDate: findColIndex(headerRow, 'DELIVERYDATE'),
      cnDdrNo: findColIndex(headerRow, 'CNDDRNO'),
      cnAdrNo: findColIndex(headerRow, 'CNADRNO'),
      cnAdrDate: findColIndex(headerRow, 'CNADRDATE'),
      cnManualCnNo: findColIndex(headerRow, 'CNMANUALCNNO'),
      cnAmount: findColIndex(headerRow, 'CNAMOUNT'),
      tptrMode: findColIndex(headerRow, 'TPTRMODE'),
      loadType: findColIndex(headerRow, 'LOADTYPE'),
      customerType: findColIndex(headerRow, 'CUSTOMERTYPE'),
      verifiedFlg: findColIndex(headerRow, 'VERIFIEDFLG'),
      stopAutoBilling: findColIndex(headerRow, 'STOPAUTOBILLING')
    };

    if (col.cnCnNo === -1){
      return { error: "This file is missing CN_CN_NO. Columns found: " + headerRow.filter(Boolean).join(', ') };
    }

    var rows = [];
    var noBcodeRows = [];
    var droppedNoBcode = 0, notFoundInMaster = 0;

    dataRows.forEach(function(row){
      var cnCnNoRaw = row[col.cnCnNo];
      var rawBcode = deriveBcodeFromCnNo(cnCnNoRaw);
      var hasBcode = rawBcode !== null;

      var finalBcode = '', branchName = '', regionName = '', remark = '';
      if (hasBcode){
        var resolved = resolveFinalBranch(rawBcode);
        finalBcode = resolved.bcode;
        branchName = resolved.entry ? resolved.entry.branch : '';
        regionName = resolved.entry ? resolved.entry.region : '';
        if (!resolved.entry){
          notFoundInMaster++;
          remark = 'Branch not in master';
        }
      } else {
        // CN_CN_NO doesn't follow the <BCODE><YY><serial> pattern — keep the
        // row anyway (blank B.CODE/BRANCH/REGION) instead of silently dropping it.
        droppedNoBcode++;
        remark = "Can't derive B.CODE from CN_CN_NO";
      }

      var manualCnNo = col.cnManualCnNo >= 0 ? row[col.cnManualCnNo] : null;
      var cnNo = truthyNum(manualCnNo) ? manualCnNo : cnCnNoRaw;

      // Customer_Type and PARTY NAME both come out of BLLING_PARTY_DETAILS,
      // a comma-joined string like "OLDPTP,PURWANOO POWER PACKS,102,RTL" —
      // first segment is the customer type (OLDPTP/RETAIL/etc), second is the
      // party name. CUSTOMER_TYPE column itself is a coarser RTL/PTP flag and
      // isn't what the report shows here.
      // Customer_Type and PARTY NAME both come ONLY out of BLLING_PARTY_DETAILS
      // ("RETAIL,JOGMAYA COPPER & BRASS FITTING,305,RTL" -> Customer_Type =
      // RETAIL, PARTY NAME = JOGMAYA COPPER & BRASS FITTING; the trailing
      // "305,RTL" is discarded). The raw CUSTOMER_TYPE column (a plain
      // RTL/SPL flag) is never used here, even as a fallback.
      var billingDetails = col.billingPartyDetails >= 0 ? row[col.billingPartyDetails] : null;
      var custType = '', partyName = '';
      if (billingDetails !== null && billingDetails !== undefined && String(billingDetails).trim() !== ''){
        var parts = String(billingDetails).split(',');
        custType = parts[0] ? parts[0].trim().replace(/\s+/g, ' ') : '';
        partyName = parts[1] ? parts[1].trim().replace(/\s+/g, ' ') : '';
      }

      var get = function(idx){ return idx >= 0 ? row[idx] : null; };

      var outRow = [
        finalBcode, branchName, regionName, cnNo, remark,
        get(col.cnDate), custType, get(col.fromSource), get(col.toDist), get(col.cnr), get(col.cee),
        get(col.billingPartyCode), partyName,
        get(col.cnPkg), get(col.cnWeight), get(col.frightMode), get(col.deliveryDate),
        get(col.cnDdrNo), get(col.cnAdrNo), get(col.cnAdrDate),
        get(col.cnAmount), get(col.tptrMode), get(col.loadType),
        get(col.verifiedFlg), get(col.stopAutoBilling)
      ];

      rows.push(outRow);
      if (!hasBcode) noBcodeRows.push(outRow);
    });

    rows.sort(function(a, b){
      var an = (typeof a[0] === 'number') ? a[0] : Infinity;
      var bn = (typeof b[0] === 'number') ? b[0] : Infinity;
      return an - bn; // stable in modern JS engines; blanks sort last
    });

    return {
      headers: PAID_GEN_OUTPUT_HEADERS, rows: rows, noBcodeRows: noBcodeRows,
      totalRaw: dataRows.length, kept: rows.length,
      droppedNoBcode: droppedNoBcode, notFoundInMaster: notFoundInMaster
    };
  }

  function renderFlatTable(headers, rows){
    var wrap = document.createElement('div');
    wrap.className = 'table-wrap';
    var table = document.createElement('table');
    table.className = 'report-table';

    var thead = document.createElement('thead');
    var htr = document.createElement('tr');
    headers.forEach(function(h, i){
      var th = document.createElement('th');
      th.textContent = h;
      th.className = i === 0 ? 'col-bcode' : (i === 1 ? 'col-branch' : (i === 2 ? 'col-region' : (i === 4 ? 'col-remark' : '')));
      htr.appendChild(th);
    });
    thead.appendChild(htr);
    table.appendChild(thead);

    var tbody = document.createElement('tbody');
    rows.forEach(function(line){
      var tr = document.createElement('tr');
      var remark = line[4];
      if (remark === 'No CHLN/DDR ref') tr.className = 'row-warn';
      else if (remark === 'Branch not in master') tr.className = 'row-notice';
      line.forEach(function(val, i){
        var td = document.createElement('td');
        td.textContent = (val === null || val === undefined) ? '' : val;
        td.className = i === 0 ? 'col-bcode' : (i === 1 ? 'col-branch' : (i === 2 ? 'col-region' : (i === 4 ? 'col-remark' : '')));
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);

    wrap.appendChild(table);
    return wrap;
  }

  function parseMasterWorkbook(workbook){
    for (var s = 0; s < workbook.SheetNames.length; s++){
      var sheet = workbook.Sheets[workbook.SheetNames[s]];
      var rows2d = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null, blankrows: false });
      for (var hr = 0; hr < Math.min(rows2d.length, 6); hr++){
        var headerRow = (rows2d[hr] || []).map(function(h){ return h == null ? '' : String(h); });
        var bIdx = findColIndex(headerRow, 'BCODE');
        var brIdx = findColIndex(headerRow, 'BRANCHNAME') !== -1 ? findColIndex(headerRow, 'BRANCHNAME') : findColIndex(headerRow, 'BRANCH');
        var rgIdx = findColIndex(headerRow, 'REGIONNAME') !== -1 ? findColIndex(headerRow, 'REGIONNAME') : findColIndex(headerRow, 'REGION');
        var ctrlIdx = findColIndex(headerRow, 'CONTROLINGBRANCH') !== -1 ? findColIndex(headerRow, 'CONTROLINGBRANCH') : findColIndex(headerRow, 'CONTROLLINGBRANCH');
        if (bIdx !== -1 && brIdx !== -1){
          var out = [];
          for (var r = hr + 1; r < rows2d.length; r++){
            var row = rows2d[r];
            if (!row || row[bIdx] == null || row[bIdx] === '') continue;
            var bcode = parseInt(row[bIdx], 10);
            if (isNaN(bcode)) continue;
            var branch = brIdx >= 0 && row[brIdx] != null ? String(row[brIdx]).trim() : '';
            var region = rgIdx >= 0 && row[rgIdx] != null ? String(row[rgIdx]).trim() : '';
            var ctrl = ctrlIdx >= 0 && row[ctrlIdx] != null && row[ctrlIdx] !== '' ? parseInt(row[ctrlIdx], 10) : null;
            out.push([bcode, branch, region, isNaN(ctrl) ? null : ctrl]);
          }
          if (out.length) return out;
        }
      }
    }
    return null;
  }

  /* ---------- Block (per-sheet) rendering ---------- */
  function analyzeSheet(name, headerRow, dataRows){
    var bcodeIdx = findColIndex(headerRow, 'BCODE');
    var branchIdx = findColIndex(headerRow, 'BRANCH');
    var cnIdx = findColIndex(headerRow, 'CNDATE');
    var deliveryIdx = findColIndex(headerRow, 'DELIVERYDATE');
    var cnNoIdx = findColIndex(headerRow, 'CNCNNO');
    var manualCnNoIdx = findColIndex(headerRow, 'CNMANUALCNNO');
    var amountIdx = findColIndex(headerRow, 'CNAMOUNT');
    var valid = bcodeIdx !== -1 && (cnIdx !== -1 || deliveryIdx !== -1);
    return {
      name: name, headerRow: headerRow, dataRows: dataRows,
      bcodeIdx: bcodeIdx, branchIdx: branchIdx, cnIdx: cnIdx, deliveryIdx: deliveryIdx,
      cnNoIdx: cnNoIdx, manualCnNoIdx: manualCnNoIdx, amountIdx: amountIdx, valid: valid
    };
  }

  function buildBlock(info){
    var sheetName = info.name, headerRow = info.headerRow, dataRows = info.dataRows;
    var cnIdx = info.cnIdx, deliveryIdx = info.deliveryIdx, bcodeIdx = info.bcodeIdx, branchIdx = info.branchIdx;
    var container = document.createElement('div');
    container.className = 'report-card';

    if (!info.valid){
      var errP = document.createElement('div');
      errP.className = 'error-box';
      var missing = [];
      if (bcodeIdx === -1) missing.push('B.CODE');
      if (cnIdx === -1 && deliveryIdx === -1) missing.push('CN_DATE or DELIVERY_DATE');
      errP.textContent = "Sheet \"" + sheetName + "\" is missing " + missing.join(' and ') +
        ". Columns found: " + headerRow.filter(Boolean).join(', ');
      var title = document.createElement('p');
      title.className = 'report-title';
      title.textContent = sheetName;
      container.appendChild(title);
      container.appendChild(errP);
      return container;
    }

    var detected = detectType(sheetName, headerRow);
    var defaultCol = detected === 'topay' && deliveryIdx !== -1 ? 'delivery'
                    : detected === 'paid' && cnIdx !== -1 ? 'cn'
                    : cnIdx !== -1 ? 'cn' : 'delivery';

    var title = document.createElement('p');
    title.className = 'report-title';
    title.textContent = sheetName;
    container.appendChild(title);

    var controlsRow = document.createElement('div');
    controlsRow.className = 'report-controls-row';

    var toggleWrap;
    if (cnIdx !== -1 && deliveryIdx !== -1){
      toggleWrap = document.createElement('div');
      toggleWrap.className = 'group-toggle';
      var btnCn = document.createElement('button');
      btnCn.type = 'button'; btnCn.textContent = 'CN_DATE (Paid)';
      var btnDel = document.createElement('button');
      btnDel.type = 'button'; btnDel.textContent = 'DELIVERY_DATE (ToPay)';
      toggleWrap.appendChild(btnCn);
      toggleWrap.appendChild(btnDel);
      controlsRow.appendChild(toggleWrap);
    } else {
      var fixedLabel = document.createElement('span');
      fixedLabel.className = 'fixed-group-label';
      fixedLabel.textContent = 'Grouped by ' + (cnIdx !== -1 ? 'CN_DATE' : 'DELIVERY_DATE');
      controlsRow.appendChild(fixedLabel);
    }

    var downloadBtn = document.createElement('button');
    downloadBtn.type = 'button';
    downloadBtn.className = 'download-btn';
    downloadBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="none"><path d="M12 3v12m0-12l-4 4m4-4l4 4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/><path d="M4 17v2a2 2 0 002 2h12a2 2 0 002-2v-2" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg><span>Download as Excel</span>';
    controlsRow.appendChild(downloadBtn);

    container.appendChild(controlsRow);

    var summary = document.createElement('p');
    summary.className = 'report-summary';
    container.appendChild(summary);

    var tableSlot = document.createElement('div');
    container.appendChild(tableSlot);

    var fallbackBox = document.createElement('div');
    fallbackBox.className = 'fallback-box';
    fallbackBox.hidden = true;
    container.appendChild(fallbackBox);

    var currentPivot = null;
    var noDateLabelFor = function(col){ return col === 'cn' ? 'No CN_DATE' : 'No Delivery Date'; };

    function renderWith(col){
      var idx = col === 'cn' ? cnIdx : deliveryIdx;
      currentPivot = buildPivot(dataRows, bcodeIdx, branchIdx, idx, noDateLabelFor(col));
      var summaryText = currentPivot.totalRecords.toLocaleString() + ' records · ' +
        currentPivot.bcodeCount.toLocaleString() + ' B.CODEs · ' + currentPivot.monthCount + ' months';
      if (currentPivot.showNoDate){
        summaryText += ' · ';
      }
      summary.textContent = summaryText;
      if (currentPivot.showNoDate){
        var warn = document.createElement('span');
        warn.className = 'warn';
        warn.textContent = currentPivot.noDateTotal.toLocaleString() + ' with no usable date';
        summary.appendChild(warn);
      }
      tableSlot.innerHTML = '';
      tableSlot.appendChild(renderTable(currentPivot));
      fallbackBox.hidden = true;
      fallbackBox.innerHTML = '';
      if (toggleWrap){
        btnCn.className = col === 'cn' ? 'active' : '';
        btnDel.className = col === 'delivery' ? 'active' : '';
      }
    }

    if (toggleWrap){
      btnCn.addEventListener('click', function(){ renderWith('cn'); });
      btnDel.addEventListener('click', function(){ renderWith('delivery'); });
    }

    downloadBtn.addEventListener('click', function(){
      if (!currentPivot) return;
      exportPivotToExcel(currentPivot, sheetName, downloadBtn, fallbackBox);
    });

    renderWith(defaultCol);
    return container;
  }

  /* ---------- Workbook processing ---------- */
  function processWorkbook(workbook, displayName){
    var tabsBar = document.getElementById('tabsBar');
    var reportsContainer = document.getElementById('reportsContainer');
    var pageError = document.getElementById('pageError');
    tabsBar.innerHTML = ''; tabsBar.hidden = true;
    reportsContainer.innerHTML = '';
    pageError.hidden = true;

    var sheetNames = workbook.SheetNames.filter(function(name){
      var sheet = workbook.Sheets[name];
      var rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null, blankrows: false });
      return rows.length > 1;
    });

    if (sheetNames.length === 0){
      pageError.textContent = 'This file has no data rows to read.';
      pageError.hidden = false;
      return;
    }

    loadedBlocks = [];
    var blocks = sheetNames.map(function(name){
      var sheet = workbook.Sheets[name];
      var rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null, blankrows: false });
      var headerRow = rows[0].map(function(h){ return h == null ? '' : String(h); });
      var dataRows = rows.slice(1);
      var info = analyzeSheet(name, headerRow, dataRows);
      loadedBlocks.push(info);
      return { name: name, el: buildBlock(info) };
    });

    var askCard = document.getElementById('askCard');
    var askLog = document.getElementById('askLog');
    var anyValid = loadedBlocks.some(function(b){ return b.valid; });
    askCard.hidden = !anyValid;
    if (askLog) askLog.innerHTML = '';

    if (blocks.length > 1){
      tabsBar.hidden = false;
      blocks.forEach(function(block, i){
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'tab-btn' + (i === 0 ? ' active' : '');
        btn.textContent = block.name;
        btn.addEventListener('click', function(){
          Array.prototype.forEach.call(tabsBar.children, function(b){ b.className = 'tab-btn'; });
          btn.className = 'tab-btn active';
          blocks.forEach(function(b2, j){ b2.el.style.display = j === i ? '' : 'none'; });
        });
        tabsBar.appendChild(btn);
      });
    }

    blocks.forEach(function(block, i){
      if (blocks.length > 1 && i !== 0) block.el.style.display = 'none';
      reportsContainer.appendChild(block.el);
    });
  }

  /* ---------- File handling ---------- */
  function handleFile(file){
    var pageError = document.getElementById('pageError');
    var fileMeta = document.getElementById('fileMeta');
    pageError.hidden = true;

    var reader = new FileReader();
    reader.onload = function(e){
      try{
        var data = new Uint8Array(e.target.result);
        var workbook = XLSX.read(data, { type: 'array', cellDates: true });
        fileMeta.hidden = false;
        fileMeta.innerHTML = '';
        var strong = document.createElement('strong');
        strong.textContent = file.name;
        fileMeta.appendChild(document.createTextNode('Loaded '));
        fileMeta.appendChild(strong);
        processWorkbook(workbook, file.name);
      }catch(err){
        pageError.textContent = "Couldn't read this file. Make sure it's a valid .xlsx, .xls or .csv export. (" + (err && err.message ? err.message : 'unknown error') + ')';
        pageError.hidden = false;
      }
    };
    reader.onerror = function(){
      pageError.textContent = "Couldn't read this file from disk. Please try again.";
      pageError.hidden = false;
    };
    reader.readAsArrayBuffer(file);
  }

  /* ---------- Ask form wiring ---------- */
  var askForm = document.getElementById('askForm');
  var askInput = document.getElementById('askInput');
  var askLogEl = document.getElementById('askLog');

  askForm.addEventListener('submit', function(e){
    e.preventDefault();
    var q = askInput.value.trim();
    if (!q) return;
    var results = answerQuery(q);

    var entry = document.createElement('div');
    entry.className = 'ask-entry';
    var qEl = document.createElement('p');
    qEl.className = 'ask-q';
    qEl.textContent = q;
    entry.appendChild(qEl);

    results.forEach(function(res){
      if (res.type === 'text'){
        var p = document.createElement('p');
        p.className = 'ask-line';
        p.textContent = res.text;
        entry.appendChild(p);
      } else if (res.type === 'docket'){
        var head = document.createElement('p');
        head.className = 'ask-line';
        head.style.fontWeight = '600';
        head.textContent = res.heading;
        entry.appendChild(head);
        var grid = document.createElement('div');
        grid.className = 'docket-grid';
        res.pairs.forEach(function(pair){
          var lab = document.createElement('span');
          lab.className = 'docket-label';
          lab.textContent = pair[0];
          var val = document.createElement('span');
          val.className = 'docket-value';
          val.textContent = pair[1];
          grid.appendChild(lab);
          grid.appendChild(val);
        });
        entry.appendChild(grid);
      }
    });

    askLogEl.insertBefore(entry, askLogEl.firstChild);
    askInput.value = '';
    askInput.focus();
  });

  /* ---------- Upload zone wiring ---------- */
  var uploadZone = document.getElementById('uploadZone');
  var fileInput = document.getElementById('fileInput');
  var browseBtn = document.getElementById('browseBtn');

  browseBtn.addEventListener('click', function(e){ e.stopPropagation(); fileInput.click(); });
  uploadZone.addEventListener('click', function(){ fileInput.click(); });
  uploadZone.addEventListener('keydown', function(e){
    if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); fileInput.click(); }
  });
  fileInput.addEventListener('change', function(){
    if (fileInput.files && fileInput.files[0]) handleFile(fileInput.files[0]);
  });
  ['dragenter','dragover'].forEach(function(evt){
    uploadZone.addEventListener(evt, function(e){
      e.preventDefault(); e.stopPropagation();
      uploadZone.classList.add('dragover');
    });
  });
  ['dragleave','drop'].forEach(function(evt){
    uploadZone.addEventListener(evt, function(e){
      e.preventDefault(); e.stopPropagation();
      uploadZone.classList.remove('dragover');
    });
  });
  uploadZone.addEventListener('drop', function(e){
    var files = e.dataTransfer && e.dataTransfer.files;
    if (files && files[0]) handleFile(files[0]);
  });

