  function fetchTopayFromMetabase(){
    var btn = document.getElementById('fetchGenerateBtn');
    var status = document.getElementById('fetchStatus');
    var errBox = document.getElementById('fetchError');
    var rawErrBox = document.getElementById('rawPageError');
    errBox.hidden = true;
    rawErrBox.hidden = true;

    var verified = (document.getElementById('fetchVerified').value || '*').trim() || '*';
    var distCode = (document.getElementById('fetchDistCode').value || '*').trim() || '*';
    var fromDate = document.getElementById('fetchFromDate').value;
    var toDate = document.getElementById('fetchToDate').value;

    if (!fromDate || !toDate){
      errBox.textContent = 'Pick both a Cn From Date and a Cn To Date first.';
      errBox.hidden = false;
      return;
    }

    var payload = {
      ignore_cache: false,
      collection_preview: false,
      parameters: [
        { id: METABASE_PARAM_IDS.verified, type: 'string/=', target: ['variable', ['template-tag', 'verified']], value: [verified] },
        { id: METABASE_PARAM_IDS.distCode, type: 'string/=', target: ['variable', ['template-tag', 'p_dist_code']], value: [distCode] },
        { id: METABASE_PARAM_IDS.fromDate, type: 'date/single', target: ['variable', ['template-tag', 'p_cn_fr_dt']], value: fromDate },
        { id: METABASE_PARAM_IDS.toDate, type: 'date/single', target: ['variable', ['template-tag', 'p_cn_to_dt']], value: toDate }
      ]
    };

    var originalLabel = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<span>Fetching…</span>';
    status.textContent = '';

    fetch(METABASE_BASE + '/api/card/' + METABASE_CARD_ID + '/query/json', {
      method: 'POST',
      headers: { 'accept': 'application/json', 'content-type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify(payload)
    })
    .then(function(res){
      if (!res.ok){
        return res.text().then(function(bodyText){
          var detail = '';
          try {
            var parsed = JSON.parse(bodyText);
            detail = parsed && parsed.error ? parsed.error : (parsed && parsed.message ? parsed.message : bodyText);
          } catch (e){
            detail = bodyText;
          }
          throw new Error('HTTP ' + res.status + (detail ? ' — ' + detail.slice(0, 300) : '.'));
        });
      }
      return res.json();
    })
    .then(function(json){
      var headerRow, dataRows;
      if (Array.isArray(json)){
        // /query/json export format: an array of {col: value} objects.
        // IMPORTANT: don't derive the column list from json[0] alone — if a
        // nullable column (e.g. CN_DDR_NO, ~20% null) happens to be null/absent
        // on the first row and the export drops null keys, that whole column
        // would silently vanish for every row, breaking CHLN/DDR branch-code
        // derivation inconsistently from run to run. Use the fixed column list
        // from card 546's own SELECT instead, so every row is read the same way
        // regardless of which fields are null on any particular row.
        headerRow = CARD_546_COLUMNS.slice();
        dataRows = json.map(function(obj){
          return headerRow.map(function(h){
            return Object.prototype.hasOwnProperty.call(obj, h) ? obj[h] : null;
          });
        });
        if (json.length){
          var seenKeys = {};
          var sampleSize = Math.min(json.length, 25);
          for (var si = 0; si < sampleSize; si++){
            for (var k in json[si]) if (Object.prototype.hasOwnProperty.call(json[si], k)) seenKeys[k] = true;
          }
          var unknownKeys = Object.keys(seenKeys).filter(function(k){ return headerRow.indexOf(k) === -1; });
          if (unknownKeys.length){
            console.warn('OmInsights response has columns not in CARD_546_COLUMNS:', unknownKeys);
            status.textContent = 'Note: response had unexpected extra columns (' + unknownKeys.slice(0, 3).join(', ') + ') — the query may have changed; check output carefully.';
          }
        }
      } else if (json && json.data && json.data.cols && json.data.rows){
        headerRow = json.data.cols.map(function(c){ return (c && (c.name || c.display_name)) || ''; });
        dataRows = json.data.rows;
      } else {
        throw new Error('Unexpected response shape from OmInsights.');
      }
      var sourceName = 'topay_' + fromDate + '_to_' + toDate;
      lastRawSheet = { headerRow: headerRow, dataRows: dataRows, name: sourceName };

      var result = generateTopayReport(headerRow, dataRows);
      renderTopayGenResult(result, sourceName);

      var meta = document.getElementById('rawFileMeta');
      meta.hidden = false;
      meta.innerHTML = '';
      var strong = document.createElement('strong');
      strong.textContent = dataRows.length.toLocaleString() + ' rows fetched from OmInsights (' + fromDate + ' \u2192 ' + toDate + ')';
      meta.appendChild(strong);

      status.textContent = 'Done.';
    })
    .catch(function(err){
      var msg = err && err.message ? err.message : 'Unknown error.';
      errBox.textContent = "Couldn't fetch: " + msg + " Settings me apna OmInsights login save hai? Agar phir bhi fail ho to neeche manual Excel export use karein.";
      errBox.hidden = false;
      status.textContent = '';
    })
    .finally(function(){
      btn.disabled = false;
      btn.innerHTML = originalLabel;
    });
  }

  var fetchGenerateBtn = document.getElementById('fetchGenerateBtn');
  if (fetchGenerateBtn) fetchGenerateBtn.addEventListener('click', fetchTopayFromMetabase);
  setFetchDefaultDates();

