  function downloadStyledPaidWorkbook(result, filename, downloadBtn, fallbackBox){
    var C = TOPAY_XLSX_COLORS;
    var headers = result.headers;
    var mainRows = result.rows.filter(function(r){ return r[4] !== "Can't derive B.CODE from CN_CN_NO"; });
    var noBcodeRows = result.noBcodeRows || [];

    function styleHeaderRow(row){
      row.eachCell(function(cell){
        cell.font = { bold: true, color: { argb: C.headerInk } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: C.headerBg } };
      });
      row.height = 20;
    }
    function fillRow(row, argb){
      row.eachCell(function(cell){
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: argb } };
      });
    }
    function borderRow(row){
      row.eachCell(function(cell){
        cell.border = { bottom: { style: 'thin', color: { argb: C.border } } };
      });
    }
    function autoWidth(ws){
      ws.columns.forEach(function(col, i){
        var len = headers[i] ? String(headers[i]).length : 10;
        col.width = Math.min(Math.max(len + 2, 10), 30);
      });
    }

    function addDataSheet(wb, name, rows, uniformFill){
      var ws = wb.addWorksheet(name);
      styleHeaderRow(ws.addRow(headers));
      autoWidth(ws);
      rows.forEach(function(line, idx){
        var display = line.slice();
        display[4] = ''; // never write the text flag
        var row = ws.addRow(display);
        row.getCell(2).font = { color: { argb: 'FF0066B3' }, bold: true };  // BRANCH
        row.getCell(3).font = { color: { argb: 'FFED1C24' }, bold: true };  // REGION
        if (uniformFill) fillRow(row, uniformFill);
        else if (line[4] === 'Branch not in master') fillRow(row, C.accentSoft);
        else if (idx % 2 === 1) fillRow(row, C.zebra);
        borderRow(row);
      });
      ws.views = [{ state: 'frozen', ySplit: 1 }];
      return ws;
    }

    function addSummarySheet(wb){
      var ws = wb.addWorksheet('Summary');
      ws.getColumn(1).width = 40; ws.getColumn(2).width = 16; ws.getColumn(3).width = 26;
      var title = ws.addRow(['Paid Report — Summary']);
      title.font = { bold: true, size: 14 };
      ws.addRow([]);
      [
        ['Total rows fetched', result.totalRaw],
        ['Rows in Report sheet', mainRows.length],
        ['No B.CODE derivable (see "No B.CODE" sheet)', result.droppedNoBcode || 0],
        ['Branch not in master (highlighted in Report sheet)', result.notFoundInMaster || 0]
      ].forEach(function(r){
        var row = ws.addRow(r);
        row.getCell(2).font = { bold: true };
      });
      ws.addRow([]);

      var issues = result.rows.filter(function(r){ return r[4]; });
      if (issues.length){
        styleHeaderRow(ws.addRow(['CN NO', 'B.CODE', 'ISSUE']));
        issues.forEach(function(r){
          var row = ws.addRow([r[3], r[0], r[4]]);
          var isNoBcode = r[4] === "Can't derive B.CODE from CN_CN_NO";
          fillRow(row, isNoBcode ? C.dangerSoft : C.accentSoft);
          row.getCell(3).font = { bold: true, color: { argb: isNoBcode ? C.danger : C.accent } };
          borderRow(row);
        });
      }
    }

    var originalLabel = downloadBtn.textContent;
    downloadBtn.disabled = true;
    downloadBtn.textContent = 'Preparing…';
    function finish(){
      downloadBtn.disabled = false;
      downloadBtn.textContent = originalLabel;
    }

    var wb = new ExcelJS.Workbook();
    addDataSheet(wb, 'PAID', mainRows);
    if (noBcodeRows.length) addDataSheet(wb, 'No B.CODE', noBcodeRows, C.dangerSoft);
    addSummarySheet(wb);

    wb.xlsx.writeBuffer().then(function(buffer){
      var blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      downloadsPromise.then(function(downloads){
        if (downloads){
          downloads.save({ filename: filename, data: blob }).then(finish).catch(function(err){
            finish();
            if (err && err.code === 'declined'){ return; }
            if (!tryBrowserDownload(blob, filename)) showFallback(fallbackBox, [headers].concat(mainRows));
          });
          return;
        }
        var ok = tryBrowserDownload(blob, filename);
        finish();
        if (!ok) showFallback(fallbackBox, [headers].concat(mainRows));
      });
    }).catch(function(err){
      finish();
      showFallback(fallbackBox, [headers].concat(mainRows));
    });
  }

  /* ---------- Combined Paid & ToPay generator ----------
     Reuses generatePaidReport()/generateTopayReport() as-is (same columns,
     same B.CODE logic, same master) — this mode just runs both from two
     separate raw uploads and packages the two results into one workbook,
     one sheet per report, named exactly "PAID" and "TOPAY". */
  function updateComboReadyState(){
    var btn = document.getElementById('comboDownloadBtn');
    var card = document.getElementById('comboReportCard');
    var ready = !!(comboPaidResult && comboTopayResult);
    card.hidden = !ready;
    if (ready){
      document.getElementById('comboReportSummary').textContent =
        'PAID: ' + comboPaidResult.kept.toLocaleString() + ' rows · TOPAY: ' + comboTopayResult.kept.toLocaleString() + ' rows — one workbook, two sheets.';
    }
    btn.disabled = !ready;
  }

  function handleComboPaidFile(file){
    var errBox = document.getElementById('comboPageError');
    errBox.hidden = true;
    var reader = new FileReader();
    reader.onload = function(e){
      try{
        var data = new Uint8Array(e.target.result);
        var workbook = XLSX.read(data, { type: 'array', cellDates: true });
        var sheet = workbook.Sheets[workbook.SheetNames[0]];
        var rows2d = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null, blankrows: false });
        var headerRow = (rows2d[0] || []).map(function(h){ return h == null ? '' : String(h); });
        var dataRows = rows2d.slice(1);
        var result = generatePaidReport(headerRow, dataRows);
        if (result.error){
          errBox.textContent = 'PAID file: ' + result.error;
          errBox.hidden = false;
          comboPaidResult = null;
        } else {
          comboPaidResult = result;
          comboPaidName = file.name;
          var summaryEl = document.getElementById('comboPaidSummary');
          summaryEl.className = 'combo-slot-summary ready';
          summaryEl.textContent = '✓ ' + file.name + ' — ' + result.kept.toLocaleString() + ' rows';
        }
        updateComboReadyState();
      }catch(err){
        errBox.textContent = "Couldn't read the PAID file. Make sure it's a valid .xlsx, .xls or .csv export. (" + (err && err.message ? err.message : 'unknown error') + ')';
        errBox.hidden = false;
      }
    };
    reader.onerror = function(){
      errBox.textContent = "Couldn't read the PAID file from disk. Please try again.";
      errBox.hidden = false;
    };
    reader.readAsArrayBuffer(file);
  }

