  function todayDDMMYYYY(){
    var d = new Date();
    var p2 = function(n){ return (n < 10 ? '0' : '') + n; };
    return p2(d.getDate()) + '.' + p2(d.getMonth() + 1) + '.' + d.getFullYear();
  }

  function downloadCombinedWorkbook(downloadBtn, fallbackBox){
    var C = TOPAY_XLSX_COLORS;

    function styleHeaderRow(row){
      row.eachCell(function(cell){
        cell.font = { bold: true, color: { argb: C.headerInk } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: C.headerBg } };
      });
      row.height = 20;
    }
    function fillRow(row, argb){
      row.eachCell(function(cell){ cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: argb } }; });
    }
    function borderRow(row){
      row.eachCell(function(cell){ cell.border = { bottom: { style: 'thin', color: { argb: C.border } } }; });
    }
    function autoWidth(ws, headers){
      ws.columns.forEach(function(col, i){
        var len = headers[i] ? String(headers[i]).length : 10;
        col.width = Math.min(Math.max(len + 2, 10), 30);
      });
    }
    // issue flag is always the string in column index 4 (REMARK) for both
    // generators' row shape — "" means no issue.
    function addSheet(wb, name, headers, rows, issueFillFor){
      var ws = wb.addWorksheet(name);
      styleHeaderRow(ws.addRow(headers));
      autoWidth(ws, headers);
      rows.forEach(function(line, idx){
        var display = line.slice();
        var issue = display[4];
        display[4] = ''; // never write the text flag itself
        var row = ws.addRow(display);
        row.getCell(2).font = { color: { argb: 'FF0066B3' }, bold: true };  // BRANCH
        row.getCell(3).font = { color: { argb: 'FFED1C24' }, bold: true };  // REGION
        var fill = issueFillFor(issue);
        if (fill) fillRow(row, fill);
        else if (idx % 2 === 1) fillRow(row, C.zebra);
        borderRow(row);
      });
      ws.views = [{ state: 'frozen', ySplit: 1 }];
    }

    var originalLabel = downloadBtn.textContent;
    downloadBtn.disabled = true;
    downloadBtn.textContent = 'Preparing…';
    function finish(){ downloadBtn.disabled = false; downloadBtn.textContent = originalLabel; }

    var wb = new ExcelJS.Workbook();

    addSheet(wb, 'PAID', comboPaidResult.headers, comboPaidResult.rows, function(issue){
      if (issue === "Can't derive B.CODE from CN_CN_NO") return C.dangerSoft;
      if (issue === 'Branch not in master') return C.accentSoft;
      return null;
    });
    addSheet(wb, 'TOPAY', comboTopayResult.headers, comboTopayResult.rows, function(issue){
      if (issue === 'No CHLN/DDR ref') return C.dangerSoft;
      if (issue === 'Branch not in master') return C.accentSoft;
      return null;
    });

    var filename = todayDDMMYYYY() + ' PAID&TOPAY REPORT.xlsx';

    wb.xlsx.writeBuffer().then(function(buffer){
      var blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      downloadsPromise.then(function(downloads){
        if (downloads){
          downloads.save({ filename: filename, data: blob }).then(finish).catch(function(err){
            finish();
            if (err && err.code === 'declined'){ return; }
            if (!tryBrowserDownload(blob, filename)) showFallback(fallbackBox, [comboPaidResult.headers].concat(comboPaidResult.rows));
          });
          return;
        }
        var ok = tryBrowserDownload(blob, filename);
        finish();
        if (!ok) showFallback(fallbackBox, [comboPaidResult.headers].concat(comboPaidResult.rows));
      });
    }).catch(function(err){
      finish();
      showFallback(fallbackBox, [comboPaidResult.headers].concat(comboPaidResult.rows));
    });
  }

  function normalizeCnNumber(v){
    if (v === null || v === undefined || v === '') return '';
    var s = String(v).trim();
    s = s.replace(/\.0+$/, '');       // "88632510050.0" (from Excel/number coercion) -> integer form
    s = s.replace(/[^0-9]/g, '');     // strip commas, spaces, stray text
    return s;
  }

  function parseCnNumberList(text){
    var tokens = String(text || '').split(/[\s,;]+/);
    var out = [];
    var seen = {};
    tokens.forEach(function(t){
      var n = normalizeCnNumber(t);
      if (n && !seen[n]){ seen[n] = true; out.push(n); }
    });
    return out;
  }

  function renderCompareResult(container, missingFromReport, extraInReport){
    container.innerHTML = '';
    function group(title, list, emptyText){
      var wrap = document.createElement('div');
      wrap.className = 'compare-result-group';
      var h = document.createElement('h4');
      h.textContent = title + ' (' + list.length.toLocaleString() + ')';
      wrap.appendChild(h);
      if (!list.length){
        var p = document.createElement('p');
        p.className = 'report-summary';
        p.textContent = emptyText;
        wrap.appendChild(p);
      } else {
        var chips = document.createElement('div');
        chips.className = 'chip-list';
        list.forEach(function(v){
          var span = document.createElement('span');
          span.textContent = v;
          chips.appendChild(span);
        });
        wrap.appendChild(chips);
      }
      return wrap;
    }
    container.appendChild(group('In your list but missing from this report', missingFromReport, 'None — every pasted CN is in the report.'));
    container.appendChild(group('In this report but not in your list', extraInReport, 'None — every report row was in your pasted list.'));
  }

  function handleRawFile(file){
    var errBox = document.getElementById('rawPageError');
    var meta = document.getElementById('rawFileMeta');
    errBox.hidden = true;
    var reader = new FileReader();
    reader.onload = function(e){
      try{
        var data = new Uint8Array(e.target.result);
        var workbook = XLSX.read(data, { type: 'array', cellDates: true });
        var sheet = workbook.Sheets[workbook.SheetNames[0]];
        var rows2d = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null, blankrows: false });
        var headerRow = (rows2d[0] || []).map(function(h){ return h == null ? '' : String(h); });
        var dataRows = rows2d.slice(1);
        lastRawSheet = { headerRow: headerRow, dataRows: dataRows, name: file.name };

        meta.hidden = false;
        meta.innerHTML = '';
        var strong = document.createElement('strong');
        strong.textContent = file.name;
        meta.appendChild(document.createTextNode('Loaded '));
        meta.appendChild(strong);

        var result = generateTopayReport(headerRow, dataRows);
        renderTopayGenResult(result, file.name);
      }catch(err){
        errBox.textContent = "Couldn't read this file. Make sure it's a valid .xlsx, .xls or .csv export. (" + (err && err.message ? err.message : 'unknown error') + ')';
        errBox.hidden = false;
      }
    };
    reader.onerror = function(){
      errBox.textContent = "Couldn't read this file from disk. Please try again.";
      errBox.hidden = false;
    };
    reader.readAsArrayBuffer(file);
  }

  var rawUploadZone = document.getElementById('rawUploadZone');
  var rawFileInput = document.getElementById('rawFileInput');
  var rawBrowseBtn = document.getElementById('rawBrowseBtn');

  rawBrowseBtn.addEventListener('click', function(e){ e.stopPropagation(); rawFileInput.click(); });
  rawUploadZone.addEventListener('click', function(){ rawFileInput.click(); });
  rawUploadZone.addEventListener('keydown', function(e){
    if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); rawFileInput.click(); }
  });
  rawFileInput.addEventListener('change', function(){
    if (rawFileInput.files && rawFileInput.files[0]) handleRawFile(rawFileInput.files[0]);
  });
  ['dragenter','dragover'].forEach(function(evt){
    rawUploadZone.addEventListener(evt, function(e){
      e.preventDefault(); e.stopPropagation();
      rawUploadZone.classList.add('dragover');
    });
  });
  ['dragleave','drop'].forEach(function(evt){
    rawUploadZone.addEventListener(evt, function(e){
      e.preventDefault(); e.stopPropagation();
      rawUploadZone.classList.remove('dragover');
    });
  });
  rawUploadZone.addEventListener('drop', function(e){
    var files = e.dataTransfer && e.dataTransfer.files;
    if (files && files[0]) handleRawFile(files[0]);
  });

