  function wireUploadZone(zoneId, inputId, browseId, handler){
    var zone = document.getElementById(zoneId);
    var input = document.getElementById(inputId);
    var browse = document.getElementById(browseId);
    browse.addEventListener('click', function(e){ e.stopPropagation(); input.click(); });
    zone.addEventListener('click', function(){ input.click(); });
    zone.addEventListener('keydown', function(e){
      if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); input.click(); }
    });
    input.addEventListener('change', function(){
      if (input.files && input.files[0]) handler(input.files[0]);
    });
    ['dragenter','dragover'].forEach(function(evt){
      zone.addEventListener(evt, function(e){ e.preventDefault(); e.stopPropagation(); zone.classList.add('dragover'); });
    });
    ['dragleave','drop'].forEach(function(evt){
      zone.addEventListener(evt, function(e){ e.preventDefault(); e.stopPropagation(); zone.classList.remove('dragover'); });
    });
    zone.addEventListener('drop', function(e){
      var files = e.dataTransfer && e.dataTransfer.files;
      if (files && files[0]) handler(files[0]);
    });
  }
  wireUploadZone('comboPaidUploadZone', 'comboPaidFileInput', 'comboPaidBrowseBtn', handleComboPaidFile);
  wireUploadZone('comboTopayUploadZone', 'comboTopayFileInput', 'comboTopayBrowseBtn', handleComboTopayFile);
